// Üretilen dosya: tool/ozgun/uret.py. Kimya · Mol kavramı ve kimyasal hesaplamalar (orta).
const ozChemistry9Orta = <(String, String, List<String>, String)>[
  ('Kimyada kullanılan "mol" teriminin Almanca "Molekül" sözcüğünden kısaltılarak bilim diline kazandırılması hangi kimyacıya atfedilir?', 'Wilhelm Ostwald', ['Amedeo Avogadro', 'John Dalton', 'Jöns Jacob Berzelius'], 'Mol terimini 19. yüzyılın sonlarında Wilhelm Ostwald yaygınlaştırmıştır; sözcük Almanca Molekül kelimesinden türetilmiştir.'),
  ('2019\'daki SI yeniden tanımlamasından önce bir mol nasıl tanımlanıyordu?', '12 g karbon-12\'deki atom sayısı kadar tanecik içeren miktar', ['1 g hidrojendeki atom sayısı kadar tanecik içeren madde miktarı', '16 g oksijendeki molekül sayısı kadar tanecik içeren madde miktarı', 'Normal koşullarda 22,4 L gazdaki tanecik sayısı kadar madde miktarı'], 'Eski tanım karbon-12\'ye dayanıyordu: 12 g (0,012 kg) karbon-12\'deki atom sayısı kadar tanecik 1 mol sayılıyordu. 2019\'dan beri Avogadro sabitinin sabitlenmiş değeri kullanılır.'),
  ('Mol, Uluslararası Birimler Sistemi\'nin (SI) temel birimleri arasına hangi yıl eklenmiştir?', '1971', ['1889', '1948', '1960\'taki SI kuruluşu'], 'Mol, 1971\'deki 14. Genel Ağırlık ve Ölçüler Konferansı\'nda yedinci temel birim olarak SI\'ye katılmıştır; 2019\'da ise yalnızca tanımı değiştirilmiştir.'),
  ('Brown hareketi üzerine yaptığı deneylerle Avogadro sayısını belirleyen, sayının Avogadro\'nun adıyla anılmasını öneren ve 1926 Nobel Fizik Ödülü\'nü alan bilim insanı kimdir?', 'Jean Perrin', ['Robert Millikan', 'Albert Einstein', 'Ernest Rutherford'], 'Jean Perrin, Einstein\'ın Brown hareketi kuramını deneysel olarak doğrulamış, Avogadro sayısını hesaplamış ve 1926\'da Nobel Fizik Ödülü\'nü almıştır.'),
  ('Faraday sabiti (bir mol elektronun yükü) bir tek elektronun yüküne bölünürse hangi nicelik elde edilir?', 'Avogadro sabiti', ['Gaz sabiti', 'Boltzmann sabiti', 'Planck sabiti'], 'F = NA·e olduğundan F/e oranı bir moldeki tanecik sayısını, yani Avogadro sabitini verir. Millikan\'ın elektron yükünü ölçmesi bu yolla NA\'nın hesaplanmasını sağlamıştır.'),
  ('Avogadro 1811\'de ortaya attığı hipotezle Dalton\'un atom kuramı ile Gay-Lussac\'ın hacim gözlemleri arasındaki çelişkiyi nasıl gidermiştir?', 'Gaz elementlerin iki atomlu moleküller olabileceğini söyleyerek', ['Atomların bölünebildiğini kanıtlayarak', 'Gazların hacminin sıcaklıktan bağımsız olduğunu göstererek', 'Her elementin tek atomlu olduğunu kabul ederek'], 'Avogadro, atom ile molekülü ayırt etmiş; hidrojen ve oksijen gibi gazların H₂ ve O₂ molekülleri hâlinde bulunduğunu kabul edince hacim oranları atom kuramıyla uyumlu hâle gelmiştir.'),
  ('Avogadro\'nun hipotezinin uzun süre göz ardı edildikten sonra 1860 Karlsruhe Kongresi\'nde dağıttığı makaleyle yeniden gündeme gelmesini sağlayan İtalyan kimyacı kimdir?', 'Stanislao Cannizzaro', ['Alessandro Giuseppe Volta', 'Amedeo Avogadro', 'Luigi Galvani'], 'Cannizzaro, Karlsruhe Kongresi\'nde Avogadro hipotezine dayanan tutarlı bir atom kütleleri sistemi sunmuş ve kimyacıların bu hipotezi benimsemesini sağlamıştır.'),
  ('Bir öğrencinin defterinde yalnızca "1 mol oksijen" yazıyor. Bu ifadenin hangi bakımdan belirsiz olduğu söylenebilir?', 'Atom mu O₂ molekülü mü olduğu belli değil; kütle 16 g ya da 32 g olabilir.', ['Oksijenin mol kütlesi sıcaklığa göre değiştiği için', 'Oksijen katı, sıvı ya da gaz olabileceği için tanecik sayısı değişir.', 'Oksijenin izotopları bulunduğu için mol tanımı kullanılamaz.'], 'Mol kullanırken taneciğin türü belirtilmelidir: 1 mol O atomu 16 g, 1 mol O₂ molekülü 32 g\'dır.'),
  ('Mol kütlesinin SI temel birimleriyle tutarlı birimi hangisidir?', 'kg/mol', ['g·mol', 'mol/kg', 'akb/mol'], 'Mol kütlesi kütlenin madde miktarına oranıdır; SI\'de kg/mol olarak ifade edilir. Kimyada pratiklik için çoğunlukla g/mol kullanılır.'),
  ('Bağıl atom kütlesinin (örneğin Na için 23) birimsiz bir sayı olmasının nedeni nedir?', 'Karbon-12 kütlesinin 1/12\'sine oranlanmış bir değer olması', ['Atomların kütlesinin ölçülememesi', 'Değerin gram cinsinden ölçülüp en yakın tam sayıya yuvarlanmış olması', 'Avogadro sayısıyla çarpılarak elde edilmesi'], 'Bağıl atom kütlesi, bir atomun ortalama kütlesinin karbon-12 kütlesinin on ikide birine bölünmesiyle bulunur; iki kütlenin oranı olduğu için birimi yoktur.'),
  ('Tek klor atomu içeren bir organik molekülün kütle spektrumunda, molekül kütlesindeki tepe ile iki birim daha ağır tepenin şiddet oranı yaklaşık 3:1\'dir. Bunun nedeni nedir?', 'Klor-35 ve klor-37 bolluklarının oranının yaklaşık 3:1 olması', ['Molekülün iyonlaşırken iki birim kütle kaybederek parçalanması', 'Klorun iki farklı yükte iyon oluşturması', 'Karbon-13 izotopunun bolluğunun yüksek olması'], 'Doğada klorun yaklaşık dörtte üçü ³⁵Cl, dörtte biri ³⁷Cl\'dir; bu yüzden M ve M+2 tepeleri yaklaşık 3:1 oranında görülür.'),
  ('Kütle spektrografını geliştirerek pek çok kararlı elementin izotoplarını belirleyen ve 1922 Nobel Kimya Ödülü\'nü alan bilim insanı kimdir?', 'Francis William Aston', ['Sir Joseph John Thomson', 'Frederick Soddy', 'Henry Moseley'], 'Aston, Thomson\'ın çalışmasını geliştirerek kütle spektrografını kurmuş, 200\'den fazla doğal izotopu tanımlamış ve 1922\'de Nobel Kimya Ödülü\'nü almıştır.'),
  ('Kütle spektrometresinde örneğin ölçümden önce mutlaka iyonlaştırılmasının nedeni nedir?', 'Alanlarla hızlandırılıp saptırılabilmeleri', ['Taneciklerin kütlesinin artırılarak tartılmasının kolaylaşması', 'Örneğin sıvı hâle getirilmesi', 'İzotopların birbirine dönüştürülmesi'], 'Yüksüz tanecikler elektrik ve manyetik alandan etkilenmez; iyonlaştırılan tanecikler ise kütle/yük oranlarına göre farklı yollar izler.'),
  ('Florun ortalama atom kütlesi 19,00 olarak verilir ve tam sayıya son derece yakındır. Bu durumdan en makul çıkarım hangisidir?', 'Doğada yalnızca tek bir kararlı izotopu bulunur.', ['Atom çekirdeğinde nötron bulunmaz.', 'İzotoplarının doğal bollukları birbirine tam olarak eşittir.', 'Atom kütlesi karbon-12 ile tanımlanmıştır.'], 'Flor doğada yalnızca ¹⁹F olarak bulunur; izotop karışımı olmadığı için ortalama kütle tek izotopun kütlesine eşit olur.'),
  ('Gümüşün ortalama atom kütlesi 107,87\'dir. Doğal gümüşün yalnızca ¹⁰⁷Ag ve ¹⁰⁹Ag izotoplarından oluştuğu biliniyorsa hangisi kesinlikle doğrudur?', '¹⁰⁷Ag biraz daha boldur.', ['¹⁰⁹Ag daha boldur.', 'İki izotop tam eşit bolluktadır.', 'Tek bir gümüş atomunun kütlesi 107,87 akb\'dir.'], '107,87 değeri 107 ile 109\'un ortası olan 108\'den küçüktür; ortalama hafif izotopa daha yakın olduğundan ¹⁰⁷Ag biraz daha boldur.'),
  ('İnşaatta kullanılan sıva alçısının formülü CaSO₄·½H₂O biçiminde yazılır. Formüldeki "½H₂O" ifadesi neyi anlatır?', 'İki CaSO₄ birimine bir su molekülü düştüğünü', ['Su molekülünün yarısının hidrojen içermediğini', 'Kristalde yarım su molekülleri bulunduğunu', 'Suyun kütlece yarısının buharlaştığını'], 'Su molekülü bölünemez; ½H₂O, kristalde her iki formül birimi CaSO₄ başına bir H₂O molekülü bulunduğunu gösteren mol oranıdır (2CaSO₄·H₂O).'),
  ('Nem göstergesi olarak kullanılan kobalt(II) klorür, nemli ortamdaki hidratlı hâlinden kristal suyunu kaybederek susuz hâle geçtiğinde rengi nasıl değişir?', 'Pembeden maviye', ['Maviden pembeye', 'Beyazdan sarıya', 'Yeşilden kırmızıya'], 'CoCl₂·6H₂O pembe, susuz CoCl₂ ise mavidir. Bu nedenle mavi renk kuru ortamı, pembe renk nemi gösterir.'),
  ('Bir iyonun mol kütlesi hesaplanırken (örneğin SO₄²⁻ için 96 g/mol) kazanılan ya da kaybedilen elektronların kütlesi genellikle neden ihmal edilir?', 'Elektron kütlesinin nükleonlarınkine göre çok küçük olması', ['Elektronların çekirdek dışında bulunduğu için kütlesiz sayılması', 'İyonlarda elektron sayısı her zaman protona eşit olduğu için', 'Mol kütlesi yalnızca proton sayısına bağlı olduğu için'], 'Bir elektronun kütlesi bir protonunkinin yaklaşık 1/1836\'sıdır; birkaç elektronun katkısı mol kütlesinin anlamlı basamaklarını değiştirmez.'),
  ('Aşağıdaki bileşiklerden hangisinin mol kütlesi sakkarozunkine (C₁₂H₂₂O₁₁) eşittir? (Al = 27, S = 32, O = 16, Ca = 40, P = 31, Na = 23, C = 12, H = 1)', 'Al₂(SO₄)₃', ['Ca₃(PO₄)₂', 'Na₂SO₄', 'C₆H₁₂O₆·H₂O'], 'Sakkaroz 342 g/mol\'dür. Al₂(SO₄)₃ = 2×27 + 3×96 = 342 g/mol; diğerleri 310, 142 ve 180 g/mol\'dür.'),
  ('Aşağıdaki örneklerden hangisi toplamda en fazla sayıda atom içerir?', '0,3 mol C₂H₆', ['0,5 mol SO₃', '0,6 mol H₂O', '1 mol neon gazı'], 'Atom molleri: C₂H₆ için 0,3×8 = 2,4; SO₃ için 0,5×4 = 2,0; H₂O için 0,6×3 = 1,8; Ne için 1. En çok atom C₂H₆ örneğindedir.'),
  ('Aşağıdaki örneklerden hangisinin kütlesi en büyüktür? (H = 1, C = 12, O = 16, S = 32; NA = 6×10²³)', 'Normal koşullarda 11,2 L CO₂', ['1 mol H₂O', '3×10²³ tane O₂ molekülü', '0,25 mol SO₃'], 'Kütleler: CO₂ 0,5 mol × 44 = 22 g; H₂O 18 g; O₂ 0,5 mol × 32 = 16 g; SO₃ 0,25 × 80 = 20 g. En büyük kütle CO₂\'dedir.'),
  ('Bir maddenin 0,25 molünde 9,0×10²³ tane atom bulunduğu belirleniyor. Bu maddenin bir molekülü kaç atomdan oluşur? (NA = 6,0×10²³)', '6', ['4', '3', '2,25'], '0,25 mol = 1,5×10²³ molekül. Atom/molekül oranı 9,0×10²³ / 1,5×10²³ = 6\'dır.'),
  ('Kütlenin korunumu yasası hangi tür olaylarda ölçülebilir biçimde sapma gösterir?', 'Çekirdek tepkimelerinde', ['Kapalı kapta gerçekleşen çökelme tepkimelerinde', 'Suyun buharlaşması gibi fiziksel değişimlerde', 'Gaz çıkışı engellenmiş yanma tepkimelerinde'], 'Çekirdek tepkimelerinde açığa çıkan enerji E = mc² ile hesaplanabilen bir kütle kaybına karşılık gelir; kimyasal tepkimelerdeki fark ise ölçülemeyecek kadar küçüktür.'),
  ('Klasik kimyada bir elementin eşdeğer kütlesi tanımlanırken referans olarak hangi miktar alınır?', '8 g oksijen ya da yaklaşık 1 g hidrojen', ['12 g karbonla birleşen kütle', '1 mol elektron veren metal kütlesinin iki katı kadar olan kütle', 'Normal koşullarda 22,4 L gazla birleşen kütle'], 'Eşdeğer kütle, 8 g oksijenle ya da 1,008 g hidrojenle birleşen (veya bunların yerini alan) element kütlesidir.'),
  ('Asit ve bazların birbirini belirli kütle oranlarında nötrleştirdiğini inceleyerek "stokiyometri" terimini kimyaya kazandıran Alman kimyacı kimdir?', 'Jeremias Benjamin Richter', ['Friedrich Wöhler', 'Justus Freiherr von Liebig', 'Robert Bunsen'], 'Richter, 1792\'de eşdeğer oranlar üzerine çalışmalarında stokiyometri (Yunanca stoikheion: öğe, metron: ölçü) kavramını ortaya koymuştur.'),
  ('Aynı koşullarda ölçülen 2 hacim A₂ gazı ile 1 hacim B₂ gazı artansız birleşerek 2 hacim gaz hâlinde tek bir bileşik oluşturuyor. Bileşiğin formülü hangisidir?', 'A₂B', ['AB₂', 'AB', 'A₂B₂'], 'Hacim oranları mol oranıdır: 2A₂ + B₂ → 2X. Atom korunumu için 2X\'te 4 A ve 2 B bulunur; X = A₂B olur.'),
  ('Aşağıdaki azotlu gübrelerden hangisi kütlece en yüksek azot yüzdesine sahiptir? (H = 1, C = 12, N = 14, O = 16, S = 32, K = 39)', 'Üre, CO(NH₂)₂', ['Amonyum nitrat, NH₄NO₃', 'Amonyum sülfat, (NH₄)₂SO₄', 'Potasyum nitrat, KNO₃'], 'Azot yüzdeleri: üre 28/60 ≈ %46,7; NH₄NO₃ 28/80 = %35; (NH₄)₂SO₄ 28/132 ≈ %21,2; KNO₃ 14/101 ≈ %13,9.'),
  ('FeO, Fe₂O₃ ve Fe₃O₄ oksitlerinin kütlece demir yüzdelerinin büyükten küçüğe sıralaması hangisidir? (Fe = 56, O = 16)', 'FeO > Fe₃O₄ > Fe₂O₃', ['Fe₂O₃ > Fe₃O₄ > FeO', 'Fe₃O₄ > FeO > Fe₂O₃', 'FeO > Fe₂O₃ > Fe₃O₄'], 'Demir atomu başına oksijen sayısı FeO\'da 1, Fe₃O₄\'te 1,33, Fe₂O₃\'te 1,5\'tir. Oksijen payı arttıkça demir yüzdesi azalır (%77,8 > %72,4 > %70).'),
  ('Basit formülü C₂H₅ olan bir alkanın bir molekülünde 10 hidrojen atomu bulunmaktadır. Molekül formülü hangisidir?', 'C₄H₁₀', ['C₂H₅', 'C₅H₁₀', 'C₁₀H₂₅'], 'Molekül formülü basit formülün tam katıdır: (C₂H₅)ₙ. 5n = 10 için n = 2 ve formül C₄H₁₀ (bütan) olur.'),
  ('Formaldehit (CH₂O), asetik asit (C₂H₄O₂) ve glukoz (C₆H₁₂O₆) için kütlece karbon yüzdeleri hakkında hangisi doğrudur?', 'Üçünde de eşittir.', ['Glukozda en büyüktür.', 'Formaldehitte en büyüktür.', 'Asetik asitte en küçüktür.'], 'Üçünün de basit formülü CH₂O\'dur. Kütlece yüzde bileşim basit formülden belirlendiğinden hepsinde karbon yaklaşık %40\'tır.'),
  ('Kükürt ve oksijenden oluşan bir bileşik kütlece eşit miktarlarda kükürt ve oksijen içermektedir. Bileşiğin formülü hangisidir? (S = 32, O = 16)', 'SO₂', ['SO', 'SO₃', 'S₂O₃'], 'Eşit kütlede S ve O alındığında mol oranı 1/32 : 1/16 = 1 : 2 olur; formül SO₂\'dir.'),
  ('C, H ve O içeren bir bileşiğin yakma analizinde oksijen miktarı neden doğrudan ürünlerden değil, farktan hesaplanır?', 'Yanma için dışarıdan da oksijen verildiğinden', ['Oksijen yanmada tamamen yok olduğundan', 'Oksijen atomlarının kütlesi ölçülemeyecek kadar küçük olduğundan', 'Ürünlerde oksijen içeren hiçbir madde bulunmadığından'], 'CO₂ ve H₂O\'daki oksijenin bir kısmı bileşikten, bir kısmı yakma için verilen O₂\'den gelir. Bu yüzden bileşikteki O, örnek kütlesinden C ve H kütleleri çıkarılarak bulunur.'),
  ('Gıdalardaki protein miktarını belirlemek için örnekteki azotun amonyağa dönüştürülüp titre edildiği klasik yöntem hangi kimyacının adıyla anılır?', 'Kjeldahl', ['Haber', 'Wilhelm Ostwald', 'Solvay'], 'Johan Kjeldahl 1883\'te geliştirdiği yöntemde organik azot önce amonyuma çevrilir, sonra ölçülür; protein miktarı azot miktarından hesaplanır.'),
  ('Bir molekülünde iki oksijen atomu bulunan bir bileşik kütlece %32 oksijen içermektedir. Bileşiğin mol kütlesi kaç g/mol\'dür? (O = 16)', '100', ['50', '64', '200,0'], 'Bir moldeki oksijen kütlesi 2 × 16 = 32 g\'dır. 32 g, mol kütlesinin %32\'si olduğundan mol kütlesi 32 / 0,32 = 100 g/mol\'dür.'),
  ('Yalnız C ve H içeren bir bileşik tamamen yakıldığında oluşan CO₂ ve H₂O\'nun mol sayıları eşit çıkıyor. Bileşiğin basit formülü hangisidir?', 'CH₂', ['CH', 'CH₄', 'C₂H₆O'], 'n(CO₂) = n(C) ve n(H₂O) = n(H)/2\'dir. Bu ikisi eşitse n(H) = 2n(C) olur; basit formül CH₂\'dir.'),
  ('C₂H₆ + 7/2 O₂ → 2CO₂ + 3H₂O biçiminde yazılan denklem için hangisi doğrudur?', 'Atomlar denktir; denklem 1 mol etan temel alınarak yazılmıştır.', ['Kesirli katsayı olduğundan denklem atom bakımından denk değildir.', '7/2 katsayısı yarım O₂ molekülünün tek başına tepkimeye girdiğini gösterir.', 'Bu yazım kütlenin korunumuna aykırıdır ve kullanılmaz.'], 'Katsayılar mol oranı da gösterdiğinden kesirli katsayılar kullanılabilir; örneğin 1 mol yakıt temel alınırken. İki tarafta 2 C, 6 H ve 7 O vardır.'),
  ('Denkleştirme sırasında SO₄²⁻ gibi çok atomlu bir iyonun tek bir birim olarak sayılması hangi durumda kolaylık sağlar ve doğru sonuç verir?', 'İyon tepkimede bozulmadan bir taraftan öbür tarafa geçiyorsa', ['İyonun içindeki atomlardan birinin yükseltgenme basamağı değişiyorsa', 'İyon yalnızca ürünler tarafında bulunuyorsa', 'Tepkime gaz fazında gerçekleşiyorsa'], 'Sülfat, nitrat, fosfat gibi gruplar tepkimede parçalanmadan aynı kalıyorsa tek birim gibi sayılabilir; grup parçalanıyorsa atomlar tek tek sayılmalıdır.'),
  ('Otomobil hava yastıklarında 2NaN₃(k) → 2Na(k) + 3N₂(g) tepkimesiyle azot gazı üretilir. 65 g sodyum azit tamamen ayrışırsa kaç mol N₂ oluşur? (Na = 23, N = 14)', '1,5', ['1', '3', '0,75'], 'NaN₃\'ün mol kütlesi 23 + 42 = 65 g/mol\'dür; 65 g = 1 mol. Denkleme göre 2 mol azitten 3 mol N₂ oluştuğundan 1 mol azitten 1,5 mol N₂ çıkar.'),
  ('Uzay araçlarında CO₂ tutucu olarak benzer tepkimeyi veren NaOH yerine LiOH tercih edilmesinin kütle bakımından gerekçesi nedir?', 'LiOH\'ın mol kütlesi daha küçüktür.', ['LiOH, CO₂ ile 1:1 mol oranında, NaOH ise 1:2 oranında tepkimeye girer.', 'Lityum, uzaydaki radyasyonu soğurarak astronotları korur.', 'NaOH, CO₂ ile hiç tepkimeye girmez.'], 'Her iki hidroksit de 2 mol başına 1 mol CO₂ tutar. LiOH 24 g/mol, NaOH 40 g/mol olduğundan aynı kütlede LiOH daha fazla mol içerir; fırlatma kütlesi azalır.'),
  ('İki değerlikli bir X metali X + 2HCl → XCl₂ + H₂ tepkimesini veriyor. 6 g X yeterli asitle tepkimeye girdiğinde 0,25 mol H₂ oluşuyor. X\'in atom kütlesi kaçtır?', '24', ['12', '40', '120'], 'Denkleme göre X ile H₂ mol sayıları eşittir: 0,25 mol X = 6 g. Atom kütlesi 6 / 0,25 = 24\'tür (magnezyum).'),
  ('2Na + Cl₂ → 2NaCl tepkimesinde 4,6 g Na ile 7,1 g Cl₂ tam verimle tepkimeye sokuluyor. Tepkime sonunda kapta neler bulunur? (Na = 23, Cl = 35,5)', 'Yalnızca NaCl', ['NaCl ve artan Na', 'NaCl ve artan Cl₂', 'Na, Cl₂ ve NaCl karışımı'], 'Na: 0,2 mol, Cl₂: 0,1 mol\'dür; 2 : 1 oranı tam olarak sağlandığından ikisi de tükenir ve yalnızca 11,7 g NaCl kalır.'),
  ('Pb(NO₃)₂ + 2KI → PbI₂ + 2KNO₃ tepkimesi için eşit mol sayılarında Pb(NO₃)₂ ve KI içeren çözeltiler karıştırılıyor. Hangisi doğrudur?', 'KI tükenir, Pb(NO₃)₂\'nin yarısı artar.', ['Pb(NO₃)₂ tükenir, KI\'nın yarısı artar.', 'İkisi de tamamen tükenir.', 'KI tükenir, Pb(NO₃)₂\'nin dörtte biri artar.'], '1 mol Pb(NO₃)₂ için 2 mol KI gerekir. Eşit mol alınırsa KI yetmez; n mol KI yalnızca n/2 mol Pb(NO₃)₂ harcar, yarısı artar.'),
  ('aA + bB → ürünler tepkimesinde A\'dan nₐ, B\'den n_b mol alınıyor. A\'nın sınırlayıcı bileşen olması için hangi koşul sağlanmalıdır?', 'nₐ / a < n_b / b', ['nₐ < n_b', 'nₐ / a > n_b / b', 'nₐ · a < n_b · b'], 'Her maddenin mol sayısı katsayısına bölünür; bu oran en küçük olan madde önce tükenir. Yalnızca mol sayılarını karşılaştırmak yanıltıcı olur.'),
  ('Endüstride bir tepkimede ucuz olan girenin hesaplanandan fazla (aşırı) kullanılmasının başlıca amacı nedir?', 'Pahalı girenin tamamen harcanmasını sağlamak', ['Tepkimenin mol oranlarını değiştirmek', 'Kütlenin korunumu yasasının sağlanmasını garanti altına almak', 'Ürünün mol kütlesini artırmak'], 'Ucuz bileşen aşırı alınınca pahalı bileşen sınırlayıcı olur ve mümkün olduğunca tamamen harcanır; böylece değerli hammadde israf edilmez.'),
  ('Verimi %100\'e yakın olan bir tepkimenin atom ekonomisi düşük olabilir mi?', 'Evet; istenmeyen yan ürünler de oluşuyorsa', ['Hayır; verim ile atom ekonomisi her zaman eşittir.', 'Hayır; yüksek verim yan ürün oluşmadığını kanıtlar.', 'Evet; ancak yalnızca gaz fazındaki tepkimelerde'], 'Verim, kuramsal ürünün ne kadarının elde edildiğini; atom ekonomisi ise girenlerdeki atomların ne kadarının istenen ürüne geçtiğini ölçer. Tam verimli bir tepkime de stokiyometrik yan ürün üretebilir.'),
  ('Yeşil kimyada kullanılan "E faktörü" neyi ölçer?', 'Ürün başına oluşan atık kütlesini', ['Tepkimenin enerji verimini', 'Ürünün saflık yüzdesini', 'Tepkime hızının sıcaklıkla nasıl değiştiğini gösteren oranı'], 'Roger Sheldon\'ın önerdiği E faktörü, atık kütlesinin ürün kütlesine oranıdır. Değer küçüldükçe süreç çevre açısından daha iyidir.'),
  ('Bakır ve çinkodan oluşan 20 g\'lık bir pirinç talaşı yeterli HCl ile işlendiğinde 0,2 mol H₂ açığa çıkıyor. Karışım kütlece yüzde kaç bakır içerir? (Zn = 65)', '35', ['65', '20', '50'], 'Bakır HCl ile tepkimeye girmez. 0,2 mol H₂ için 0,2 mol Zn = 13 g gerekir; bakır 7 g olup %35\'tir.'),
  ('Boyut analiziyle 24,0 g karbonun içerdiği atom sayısı hesaplanmak isteniyor. Hangi dönüşüm çarpanları doğru sırayla kullanılmalıdır? (C = 12,0)', '24,0 g × (1 mol / 12,0 g) × (6,02×10²³ atom / 1 mol)', ['24,0 g × (12,0 g / 1 mol) × (6,02×10²³ atom / 1 mol)', '24,0 g × (1 mol / 6,02×10²³ atom) × (12,0 g / 1 mol)', '24,0 g × (6,02×10²³ atom / 1 mol) ÷ (1 mol / 12,0 g) ÷ 2'], 'Birimlerin sadeleşmesi için önce g, g/mol ile (1 mol/12,0 g) mol\'e; sonra mol, (atom/mol) ile atoma çevrilir. Diğer seçeneklerde birimler sadeleşmez.'),
  ('Eski kimya kitaplarında geçen "1 gram-atom demir" ifadesi bugünkü dilde neye karşılık gelir?', '1 mol demir atomu', ['1 gram demirdeki atom sayısı', 'Bir demir atomunun gram cinsinden kütlesi', 'Demirin 1 gramlık eşdeğer kütlesi'], 'Gram-atom, atom kütlesi kadar gram element demektir; bu da 1 mol atom (demir için 56 g) anlamına gelir.'),
  ('Bir öğrenci "1 mol gaz her koşulda 22,4 L hacim kaplar." diyor. Bu ifade nasıl düzeltilmelidir?', 'Bu değer yalnızca 0 °C ve 1 atm için geçerlidir.', ['Bu değer yalnızca tek atomlu gazlar için geçerlidir.', 'Bu değer yalnızca hidrojen gazı için geçerlidir.', 'İfade doğrudur; gaz hacmi koşullara bağlı değildir.'], '22,4 L, ideal gazın normal koşullardaki (0 °C, 1 atm) molar hacmidir. Sıcaklık ya da basınç değişince molar hacim de değişir.'),
  ('Eşit kütlelerde alınan O₂ ve O₃ (ozon) örnekleri için hangisi doğrudur? (O = 16)', 'Oksijen atomu sayıları eşittir.', ['Molekül sayıları eşittir.', 'O₃ örneğinde daha çok atom vardır.', 'O₂ örneğinde daha çok atom vardır.'], 'İki örnek de yalnızca oksijen atomlarından oluştuğu için eşit kütle eşit sayıda O atomu demektir. Molekül sayıları ise 3 : 2 oranındadır (O₂ daha fazla).'),
  ('Bir öğrenci "2 mol H₂O; 2 mol H₂ ve 1 mol O₂ içerir." diyor. Bu ifadenin doğru biçimi hangisidir?', '2 mol H₂O, 4 mol H atomu ve 2 mol O atomu içerir.', ['2 mol H₂O, 2 mol H atomu ve 1 mol O atomu içerir.', 'İfade doğrudur; su H₂ ve O₂ moleküllerinden oluşur.', '2 mol H₂O, 4 mol H₂ molekülü ve 2 mol O₂ molekülü içerir.'], 'Su molekülünün içinde H₂ ya da O₂ molekülü bulunmaz; atomlar bulunur. Her H₂O\'da 2 H ve 1 O atomu olduğundan 2 mol suda 4 mol H ve 2 mol O atomu vardır.'),
  ('Etanol ve dimetil eter farklı maddeler olmasına karşın aynı molekül formülüne (C₂H₆O) sahiptir. Bu iki madde için hangisi kesinlikle doğrudur?', 'Mol kütleleri ve yüzde bileşimleri aynıdır.', ['Erime ve kaynama noktaları aynıdır.', 'Kimyasal tepkimelerdeki davranışları tamamen aynıdır.', 'Atomlarının birbirine bağlanma sırası aynıdır.'], 'Molekül formülü atom türünü ve sayısını verir; bu nedenle mol kütlesi ve yüzde bileşim aynıdır. Atomların diziliş sırası ve dolayısıyla özellikler farklıdır.'),
  ('Bir öğrenci 0,5 mol klor gazının kütlesini 0,5 × 35,5 = 17,75 g olarak buluyor. Öğrencinin yaptığı hata nedir? (Cl = 35,5)', 'Klor gazının Cl₂ olduğunu hesaba katmamıştır.', ['Klorun atom kütlesini yanlış almıştır.', 'Mol sayısını önce Avogadro sayısına bölmesi gerekirdi.', 'Klor gazı tek atomlu olduğundan hesap doğrudur.'], 'Klor gazı Cl₂ moleküllerinden oluşur; mol kütlesi 71 g/mol\'dür. 0,5 mol Cl₂ = 35,5 g olmalıdır.'),
  ('0,1 mol demir tamamen Fe³⁺ iyonlarına yükseltgenirken toplam kaç tane elektron verir? (NA = 6,0×10²³)', '1,8×10²³', ['6,0×10²²', '1,2×10²³', '3,0×10²²'], 'Her Fe atomu 3 elektron verir: 0,1 × 3 = 0,3 mol elektron = 0,3 × 6,0×10²³ = 1,8×10²³ elektron.'),
  ('Eşit mol sayılarında alınan sodyum ve alüminyum yeterli miktarda HCl ile ayrı ayrı tepkimeye giriyor. Açığa çıkan H₂ mol sayıları oranı (Na / Al) kaçtır?', '1/3', ['3', '1', '2/3'], '2Na + 2HCl → 2NaCl + H₂ ve 2Al + 6HCl → 2AlCl₃ + 3H₂. 1 mol Na 0,5 mol, 1 mol Al 1,5 mol H₂ verir; oran 0,5 / 1,5 = 1/3.'),
  ('2SO₂ + O₂ → 2SO₃ tepkimesinde 0,5 mol SO₂ tamamen SO₃\'e dönüşürken kükürt atomları toplam kaç mol elektron verir?', '1', ['0,5', '2', '3'], 'Kükürt SO₂\'de +4, SO₃\'te +6 basamağındadır; her S 2 elektron verir. 0,5 × 2 = 1 mol elektron.'),
  ('0,1 mol Al₂(SO₄)₃ içeren bir örnekteki alüminyum iyonlarının taşıdığı toplam artı yük kaç moldür (mol birim yük cinsinden)?', '0,6', ['0,2', '0,3', '1,2'], '0,1 mol tuzda 0,2 mol Al³⁺ vardır; her biri +3 yüklü olduğundan toplam 0,6 mol birim artı yük bulunur. Bu, sülfatların toplam eksi yüküne eşittir.'),
  ('Benzinin temel bileşenlerinden oktan (C₈H₁₈, 114 g/mol) 2C₈H₁₈ + 25O₂ → 16CO₂ + 18H₂O tepkimesine göre yanar. 1 kg oktan tamamen yandığında yaklaşık kaç kg CO₂ oluşur? (CO₂ = 44 g/mol)', '3,1', ['1,0', '8,0', '0,39'], '1000 / 114 ≈ 8,77 mol oktan; her mol 8 mol CO₂ verir: 70,2 mol × 44 g ≈ 3,1 kg. Ürün kütlesinin büyük olması havadaki oksijenin katılmasındandır.'),
  ('Aşağıdaki yakıtların 1\'er mollerinden hangisinin tamamen yanması için en çok O₂ gerekir?', 'Propan, C₃H₈', ['Metan, CH₄', 'Etanol, C₂H₅OH', 'Asetilen, C₂H₂'], 'CₓHᵧO_z için gereken O₂ = x + y/4 − z/2\'dir. Metan 2, etanol 3, asetilen 2,5, propan 5 mol O₂ gerektirir.'),
  ('Eşit kütlelerde H₂ ve CH₄ ayrı ayrı tamamen yakılıyor. Hidrojenin yanmasından oluşan su, metanınkinden kaç kat fazladır? (H = 1, C = 12)', '4', ['2', '8', '1/4'], 'm gram H₂ = m/2 mol, m/2 mol su verir. m gram CH₄ = m/16 mol, 2 × m/16 = m/8 mol su verir. (m/2) / (m/8) = 4.'),
  ('19. yüzyılın başında bütün elementlerin atom kütlelerinin hidrojenin atom kütlesinin tam katları olduğunu öne süren hipotez kimin adıyla anılır?', 'William Prout', ['John Dalton', 'Humphry Davy', 'Michael Faraday'], 'İngiliz hekim William Prout 1815–1816\'da bu hipotezi ileri sürmüştür; elementlerin hidrojenden oluştuğu fikrine dayanıyordu.'),
  ('Prout hipotezini (atom kütlelerinin hidrojenin tam katları olması) uzun süre zayıflatan ölçüm hangisiydi ve bu çelişki sonradan nasıl açıklandı?', 'Klorun 35,5 bulunması; izotop karışımı', ['Oksijenin 16 bulunması; elektronların kütlesi', 'Karbonun 12 bulunması; bağlanma enerjisi', 'Helyumun 4 bulunması; radyoaktif bozunma'], 'Klorun atom kütlesinin 35,5 çıkması tam katlar fikrine uymuyordu. 20. yüzyılda klorun ³⁵Cl ve ³⁷Cl izotoplarının karışımı olduğu anlaşıldı.'),
  ('Dalton suyun formülünü HO kabul etmişti. Suda oksijen/hidrojen kütle oranı 8 ise ve hidrojenin atom kütlesi 1 alınırsa bu varsayımla oksijenin atom kütlesi kaç bulunur?', '8', ['16', '4', '32'], 'HO formülünde bir O atomu bir H atomunun 8 katı kütleli olmalıdır; O = 8 bulunur. Gerçek formül H₂O olduğundan doğru değer 16\'dır; yanlış formül varsayımı atom kütlesini yarıya indirmiştir.'),
  ('Solvay yönteminin net tepkimesi CaCO₃ + 2NaCl → Na₂CO₃ + CaCl₂ olarak yazılabilir. 106 kg soda (Na₂CO₃) üretmek için en az kaç kg NaCl gerekir? (Na = 23, Cl = 35,5, C = 12, O = 16)', '117', ['58,5', '106', '234'], '106 kg Na₂CO₃ = 1 kmol\'dür ve 2 kmol NaCl gerektirir: 2 × 58,5 = 117 kg.'),
  ('Alüminyum üretiminin net tepkimesi 2Al₂O₃ → 4Al + 3O₂ olarak özetlenebilir. 1 ton alüminyum elde etmek için kuramsal olarak en az kaç ton Al₂O₃ gerekir? (Al = 27, O = 16)', '1,89', ['1,00', '0,53', '3,78'], 'Al₂O₃\'ün 102 kütle biriminden 54\'ü alüminyumdur. 1 ton Al için 102/54 ≈ 1,89 ton Al₂O₃ gerekir.'),
  ('Klor-alkali sürecinde 2NaCl + 2H₂O → 2NaOH + H₂ + Cl₂ tepkimesi gerçekleşir. 117 kg NaCl tamamen tepkimeye girerse kaç kg Cl₂ elde edilir? (Na = 23, Cl = 35,5)', '71', ['35,5', '117', '142'], '117 kg NaCl = 2 kmol\'dür; 2 kmol NaCl\'den 1 kmol Cl₂ oluşur: 71 kg.'),
  ('Cam üretiminde Na₂CO₃ + SiO₂ → Na₂SiO₃ + CO₂ tepkimesi gerçekleşir. 60 kg kumla (SiO₂) tam tepkimeye girecek soda kaç kilogramdır? (Si = 28, O = 16, Na = 23, C = 12)', '106', ['60', '53', '212'], '60 kg SiO₂ = 1 kmol\'dür; 1 : 1 oranında 1 kmol Na₂CO₃ = 106 kg gerekir.'),
  ('Kara barutun yanması 2KNO₃ + S + 3C → K₂S + N₂ + 3CO₂ denklemiyle gösterilir. 0,2 mol KNO₃ tamamen tepkimeye girdiğinde toplam kaç mol gaz oluşur?', '0,4', ['0,2', '0,3', '0,8'], '2 mol KNO₃ başına 1 mol N₂ ve 3 mol CO₂ (4 mol gaz) oluşur. 0,2 mol KNO₃ için 0,1 + 0,3 = 0,4 mol gaz.'),
  ('Titanyum Kroll yöntemiyle TiCl₄ + 2Mg → Ti + 2MgCl₂ tepkimesinden elde edilir. 48 kg titanyum üretmek için en az kaç kg magnezyum gerekir? (Ti = 48, Mg = 24)', '48', ['24', '96', '12'], '48 kg Ti = 1 kmol\'dür ve 2 kmol Mg gerektirir: 2 × 24 = 48 kg.'),
  ('Kütlece %2 kükürt içeren 1 ton kömür yakıldığında kükürdün tamamı S + O₂ → SO₂ ile dönüşürse kaç kilogram SO₂ oluşur? (S = 32, O = 16)', '40', ['20', '0,625', '64'], '1 tonda 20 kg kükürt vardır; 20/32 = 0,625 kmol S, aynı mol SO₂ verir: 0,625 × 64 = 40 kg.'),
  ('Termik santral bacalarında SO₂, kireç taşıyla 2CaCO₃ + 2SO₂ + O₂ → 2CaSO₄ + 2CO₂ tepkimesine göre tutulur. 64 kg SO₂\'yi tutmak için en az kaç kg CaCO₃ gerekir? (CaCO₃ = 100, SO₂ = 64 g/mol)', '100', ['50', '156,25', '200'], 'CaCO₃ ile SO₂ 1 : 1 mol oranında tepkimeye girer. 64 kg SO₂ = 1 kmol, 1 kmol CaCO₃ = 100 kg gerektirir.'),
  ('Bir diş macunu tüpünde 0,22 g sodyum florür (NaF, 42 g/mol) bulunuyor. Tüpte yaklaşık kaç miligram flor vardır? (F = 19)', '100', ['220', '42', '19'], '0,22 / 42 ≈ 5,2×10⁻³ mol NaF; içindeki flor 5,2×10⁻³ × 19 ≈ 0,10 g = 100 mg\'dır.'),
  ('İyotlu sofra tuzuna eklenen 42,8 mg potasyum iyodat (KIO₃, 214 g/mol) kaç miligram iyot içerir? (I = 127)', '25,4', ['42,8', '12,7', '127,0'], '42,8 / 214 = 0,2 mmol KIO₃; her birimde bir I olduğundan 0,2 × 127 = 25,4 mg iyot.'),
  ('70 kg\'lık bir insanın vücut kütlesinin yaklaşık %60\'ı sudur. Bu insanın vücudunda yaklaşık kaç mol su vardır? (H₂O = 18 g/mol)', '2,3×10³', ['42', '3,9×10³', '7,6×10²'], '70 × 0,60 = 42 kg = 42 000 g su; 42 000 / 18 ≈ 2,3×10³ mol.'),
  ('Kirli bir kent havasında 1 m³ havada 40 µg NO₂ (46 g/mol) ölçülüyor. Bu hacimde yaklaşık kaç NO₂ molekülü vardır? (NA = 6,0×10²³)', '5,2×10¹⁷', ['8,7×10⁻⁷', '2,4×10²⁵', '5,2×10¹¹'], '40 µg = 4,0×10⁻⁵ g; 4,0×10⁻⁵ / 46 ≈ 8,7×10⁻⁷ mol; × 6,0×10²³ ≈ 5,2×10¹⁷ molekül.'),
  ('Saf bir maddenin kütlesi yatay eksende, mol sayısı düşey eksende gösterildiğinde başlangıçtan geçen bir doğru elde edilir. Bu doğrunun eğimi neye eşittir?', '1/M değerine', ['M değerine', 'Avogadro sayısına', 'Maddenin yoğunluğuna'], 'n = m / M olduğundan n, m ile doğru orantılıdır ve orantı sabiti 1/M\'dir. Mol kütlesi büyük maddelerin doğrusu daha yatık olur.'),
  ('Bir molekülünün kütlesi m gram olan bir maddenin mol kütlesi hangi ifadeyle verilir? (NA: Avogadro sayısı)', 'm·NA g/mol', ['m/NA g/mol', 'NA/m g/mol', 'm/(12·NA) g/mol'], '1 mol, NA tane molekül içerir; kütlesi m × NA gramdır. Bu da mol kütlesinin sayısal değeridir.'),
  ('Bir bileşiğin 0,1 molü 2,4 g karbon ve 0,6 g hidrojen içermektedir ve başka element yoktur. Bileşiğin molekül formülü hangisidir? (C = 12, H = 1)', 'C₂H₆', ['CH₃', 'C₂H₄', 'C₄H₁₂'], '1 molde 24 g C (2 mol) ve 6 g H (6 mol) bulunur. Bir molekülde 2 C ve 6 H olduğundan formül C₂H₆\'dır.'),
  ('Ca(NO₃)₂·4H₂O formülüyle gösterilen hidratın bir formül biriminde toplam kaç atom vardır?', '21', ['13', '15', '27'], 'Ca(NO₃)₂: 1 Ca + 2 N + 6 O = 9 atom; 4H₂O: 4 × 3 = 12 atom. Toplam 21 atom.'),
  ('0,1 mol CuSO₄·5H₂O kristalinde toplam kaç mol oksijen atomu bulunur?', '0,9', ['0,4', '0,5', '1,4'], 'Her formül biriminde sülfattan 4, kristal suyundan 5 olmak üzere 9 oksijen vardır. 0,1 × 9 = 0,9 mol.'),
  ('X₂ + 3Y₂ → 2Z tepkimesinde 0,6 mol Y₂ harcandığında 6,8 g Z oluşuyor. Z\'nin mol kütlesi kaç g/mol\'dür?', '17', ['34', '11,3', '8,5'], 'Y₂ ile Z\'nin mol oranı 3 : 2\'dir; 0,6 mol Y₂ 0,4 mol Z verir. 6,8 / 0,4 = 17 g/mol (örneğin NH₃).'),
  ('2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O tepkimesinde 2 mol etan ile 7 mol O₂ yüksek sıcaklıkta tam verimle tepkimeye giriyor ve su buhar hâlinde kalıyor. Tepkime sonunda kaç mol gaz bulunur?', '10', ['9', '4', '13'], 'Girenler tamamen tükenir; 4 mol CO₂ ve 6 mol H₂O buharı oluşur. Toplam gaz 10 mol\'dür (başlangıçta 9 mol vardı).'),
  ('0,2 mol X ile 0,3 mol Y elementleri artansız birleşerek 0,1 mol bileşik oluşturuyor. Bileşiğin formülü hangisidir?', 'X₂Y₃', ['XY', 'X₃Y₂', 'XY₃'], '0,1 mol bileşikte 0,2 mol X ve 0,3 mol Y bulunur; bir formül biriminde 2 X ve 3 Y vardır.'),
  ('C₃H₈ + 5O₂ → 3CO₂ + 4H₂O tepkimesi sonunda kapta 0,1 mol propan artmış ve 0,9 mol CO₂ oluşmuştur. Başlangıçta kaç mol propan vardı?', '0,4', ['0,3', '0,9', '1,0'], '0,9 mol CO₂ için 0,3 mol propan harcanmıştır. Başlangıçtaki propan 0,3 + 0,1 = 0,4 mol\'dür.'),
  ('Bir gazın 2 molü 88 g geliyor. Yalnızca bu veriye dayanarak gazın kimliği hakkında ne söylenebilir? (H = 1, C = 12, N = 14, O = 16)', 'Kesin belirlenemez; birden çok gaz olabilir.', ['Kesinlikle CO₂\'dir.', 'Kesinlikle C₃H₈\'dir.', 'Mol kütlesi hesaplanamaz; çünkü sıcaklık ve basınç verilmemiştir.'], 'Mol kütlesi 88 / 2 = 44 g/mol\'dür. CO₂, N₂O ve C₃H₈\'in üçü de 44 g/mol olduğundan yalnız mol kütlesi gazı tanımaya yetmez.'),
  ('Yoğunluğu 13,6 g/mL olan cıvanın 1 mL\'sinde yaklaşık kaç cıva atomu bulunur? (Hg = 200,6; NA = 6,02×10²³)', '4,1×10²²', ['6,0×10²³', '8,2×10²⁴', '4,4×10²¹'], '1 mL cıva 13,6 g\'dır; 13,6 / 200,6 ≈ 0,068 mol. 0,068 × 6,02×10²³ ≈ 4,1×10²² atom.'),
  ('Okul laboratuvarlarında Avogadro sayısını kestirmek için su yüzeyine damlatılan oleik asidin tek molekül kalınlığında bir tabaka hâlinde yayılması sağlanır. Bu deneyde ölçülen temel büyüklükler hangileridir?', 'Damla hacmi ve leke alanı', ['Suyun sıcaklığı ve ortamın basıncı', 'Oleik asidin kaynama noktası ve rengi', 'Damlanın düşme hızı ve yüksekliği'], 'Hacim alana bölünerek tabakanın kalınlığı, yani yaklaşık molekül boyutu bulunur. Bir molekülün hacminden ve mol hacminden Avogadro sayısı kestirilir.'),
  ('CuSO₄ çözeltisinin elektrolizinde devreden 2 mol elektron geçtiğinde katotta biriken bakır miktarı ile aynı yük AgNO₃ çözeltisinden geçtiğinde biriken gümüş miktarının mol oranı (Cu / Ag) kaçtır?', '1/2', ['2/1', '1', '1/4'], 'Cu²⁺ için 2 elektron, Ag⁺ için 1 elektron gerekir. 2 mol elektron 1 mol Cu ya da 2 mol Ag biriktirir; oran 1/2\'dir.'),
  ('Bir elektroliz hücresinde katotta 2H⁺ + 2e⁻ → H₂ tepkimesiyle 1 mol elektron başına normal koşullarda kaç litre hidrojen gazı toplanır?', '11,2', ['22,4', '5,6', '44,8'], '2 mol elektron 1 mol H₂ verir. 1 mol elektron 0,5 mol H₂, yani 0,5 × 22,4 = 11,2 L oluşturur.'),
  ('Gıdalardaki protein miktarı, proteinin kütlece ortalama %16 azot içerdiği varsayılarak azot miktarından hesaplanır. Analizde 1,6 g azot bulunan bir örnek kaç gram protein içerir?', '10', ['1,6', '16', '6,25'], 'Protein kütlesi = azot kütlesi / 0,16 = 1,6 / 0,16 = 10 g. Bu, azotun 6,25 katsayısıyla çarpılmasına eşdeğerdir.'),
  ('Mol yüzdesi %80 N₂ ve %20 O₂ olan bir gaz karışımının ortalama mol kütlesi kaç g/mol\'dür? (N₂ = 28, O₂ = 32)', '28,8', ['30', '29,6', '32,0'], 'Ortalama mol kütlesi = 0,80 × 28 + 0,20 × 32 = 22,4 + 6,4 = 28,8 g/mol.'),
  ('1 mol etanolün (C₂H₅OH) ve 1 mol etanın (C₂H₆) tamamen yanması için gereken O₂ miktarları için hangisi doğrudur?', 'Etan 0,5 mol daha fazla O₂ ister.', ['Etanol 0,5 mol daha fazla O₂ ister.', 'İkisi de eşit miktarda O₂ ister.', 'Etan 1 mol daha fazla O₂ ister.'], 'C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O; C₂H₆ + 3,5O₂ → 2CO₂ + 3H₂O. Etanoldeki oksijen atomu gereken O₂\'yi yarım mol azaltır.'),
  ('Bir öğrenci N₂ + 3H₂ → 2NH₃ denklemine bakarak "1 g azot 3 g hidrojenle tepkimeye girer." diyor. Bu yorum için hangisi doğrudur?', 'Yanlıştır; katsayılar gram değil mol oranını verir.', ['Doğrudur; katsayılar kütle oranını gösterir.', 'Doğrudur; ancak yalnız normal koşullarda geçerlidir.', 'Yanlıştır; 1 g azot 1 g hidrojenle tepkimeye girer.'], '1 mol (28 g) N₂, 3 mol (6 g) H₂ ile tepkimeye girer; kütle oranı 28 : 6\'dır. Katsayılar mol sayıları arasındaki oranı gösterir.'),
  ('Benzinli motorlarda stokiyometrik hava/yakıt kütle oranı yaklaşık 14,7\'dir. Bu oranın üzerinde, yani havanın fazla olduğu karışıma ne ad verilir?', 'Fakir karışım', ['Zengin karışım', 'Doymuş karışım', 'Kararlı karışım'], 'Hava (oksijen) gerekenden fazla olduğunda karışım fakir (yoksul) karışım olarak adlandırılır; yakıt sınırlayıcıdır ve oksijen artar.'),
  ('Bir motorda yakıtın stokiyometrik orandan fazla olduğu (zengin) karışım yakıldığında egzoz gazında hangi kirleticinin oranı belirgin biçimde artar?', 'Karbon monoksit', ['Oksijen (O₂) gazı', 'Azot gazı', 'Argon gazı'], 'Zengin karışımda oksijen sınırlayıcıdır; karbonun tamamı CO₂\'ye dönüşemez ve eksik yanma ürünü olan CO artar.'),
  ('Sınırlayıcı bileşen problemlerinde kullanılan başlangıç–değişim–son tablosunda "değişim" satırındaki mol değerleri hangi orana uymalıdır?', 'Denklemdeki katsayıların oranına', ['Başlangıçtaki mol sayılarının oranına', 'Maddelerin mol kütlelerinin oranına', 'Son durumdaki mol sayılarının oranına'], 'Tepkimeye giren ve oluşan miktarlar her zaman katsayılarla orantılıdır. Başlangıç miktarları ise keyfidir ve bu orana uymak zorunda değildir.'),
  ('X ve Y elementlerinden oluşan bir bileşikte X kütlesinin bileşik kütlesine oranı 2/5\'tir. 30 g bileşik elde etmek için kaç gram Y gerekir?', '18', ['12', '12,5', '75'], 'Bileşiğin 2/5\'i X ise 3/5\'i Y\'dir. 30 × 3/5 = 18 g Y gerekir.'),
  ('40 g CaCO₃ bir süre ısıtıldığında CaCO₃ → CaO + CO₂ tepkimesi sonucu katının kütlesi 31,2 g\'a iniyor. Başlangıçtaki CaCO₃\'ün yüzde kaçı ayrışmıştır? (Ca = 40, C = 12, O = 16)', '50', ['22', '78', '44,0'], 'Kütle kaybı 8,8 g CO₂ = 0,2 mol\'dür; bu, 0,2 mol (20 g) CaCO₃\'ün ayrıştığını gösterir. 20 / 40 × 100 = %50.'),
  ('MgCO₃ tamamen ısıtılarak MgCO₃ → MgO + CO₂ tepkimesine göre ayrıştırıldığında katının kütlesi yüzde kaç azalır? (Mg = 24, C = 12, O = 16)', '52,4', ['47,62', '44,0', '28,6'], '84 g MgCO₃\'ten 44 g CO₂ çıkar, 40 g MgO kalır. Azalma 44 / 84 × 100 ≈ %52,4\'tür.'),
  ('1 mol hidronyum iyonunda (H₃O⁺) toplam kaç mol elektron vardır? (H için Z = 1, O için Z = 8)', '10', ['11', '9', '12'], 'Proton sayısı 8 + 3 = 11\'dir; +1 yük bir elektron eksikliğini gösterdiğinden elektron sayısı 10\'dur.'),
  ('0,2 mol karbonat iyonunda (CO₃²⁻) toplam kaç mol elektron bulunur? (C için Z = 6, O için Z = 8)', '6,4', ['6,0', '5,6', '3,2'], 'Proton sayısı 6 + 3 × 8 = 30, −2 yük nedeniyle elektron sayısı 32\'dir. 0,2 × 32 = 6,4 mol elektron.'),
  ('Aşağıdaki türlerden hangisinin 1 molü, 1 mol suyun içerdiği kadar elektron içermez? (Z: H = 1, N = 7, O = 8, F = 9, Na = 11)', 'Na atomu', ['NH₄⁺ iyonu', 'OH⁻ iyonu', 'F⁻ iyonu'], 'Su molekülünde 10 elektron vardır. NH₄⁺, OH⁻ ve F⁻ de 10\'ar elektron taşır; nötr Na atomunda ise 11 elektron bulunur.'),
  ('1 g karbon-12 izotopunda toplam kaç mol nötron bulunur?', '0,5', ['1', '6', '1/12'], '1 g ¹²C = 1/12 mol atomdur. Her atomda 6 nötron olduğundan 6/12 = 0,5 mol nötron vardır.'),
  ('Kapalı ortamlarda CO₂\'yi tutup O₂ üretmek için 2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂ ya da 4KO₂ + 2CO₂ → 2K₂CO₃ + 3O₂ tepkimeleri kullanılabilir. Tutulan her mol CO₂ başına açığa çıkan O₂ için hangisi doğrudur?', 'KO₂ üç kat fazla O₂ verir.', ['Na₂O₂ üç kat fazla O₂ verir.', 'İkisi eşit miktarda O₂ verir.', 'KO₂ iki kat fazla O₂ verir.'], 'Na₂O₂ ile 2 mol CO₂ başına 1 mol (CO₂ başına 0,5 mol) O₂; KO₂ ile 2 mol CO₂ başına 3 mol (CO₂ başına 1,5 mol) O₂ oluşur. Oran 3\'tür.'),
  ('"Kimya volkanı" gösterisinde amonyum dikromat (NH₄)₂Cr₂O₇ → Cr₂O₃ + N₂ + 4H₂O tepkimesiyle ayrışır. 25,2 g amonyum dikromat tamamen ayrıştığında geriye kaç gram katı Cr₂O₃ kalır? ((NH₄)₂Cr₂O₇ = 252, Cr₂O₃ = 152 g/mol)', '15,2', ['25,2', '10,0', '30,4'], '25,2 g = 0,1 mol amonyum dikromat, 0,1 mol Cr₂O₃ verir: 0,1 × 152 = 15,2 g. Kalan kütle gaz ve buhar olarak uzaklaşır.'),
  ('Kurşun(II) nitratın ısıyla ayrışması Pb(NO₃)₂ → PbO + NO₂ + O₂ denklemiyle gösterilir. En küçük tam sayılarla denkleştirildiğinde katsayılar toplamı kaçtır?', '9', ['4', '7', '11'], '2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂ denkleminde toplam 2 + 2 + 4 + 1 = 9\'dur.'),
  ('Kızgın demir su buharıyla 3Fe + 4H₂O → Fe₃O₄ + 4H₂ tepkimesini verir. 0,3 mol demir tamamen tepkimeye girdiğinde kaç mol H₂ oluşur?', '0,4', ['0,3', '0,1', '1,2'], '3 mol Fe\'den 4 mol H₂ oluşur. 0,3 × 4/3 = 0,4 mol H₂.'),
  ('Köpüren tabletlerde sitrik asit C₆H₈O₇ + 3NaHCO₃ → Na₃C₆H₅O₇ + 3H₂O + 3CO₂ tepkimesini verir. 0,01 mol sitrik asitle tam tepkimeye girecek NaHCO₃ kaç gramdır? (NaHCO₃ = 84 g/mol)', '2,52', ['0,84', '1,68', '0,28'], '1 mol sitrik asit 3 mol NaHCO₃ ile tepkimeye girer. 0,03 mol × 84 = 2,52 g.'),
  ('2,0 g yumurta kabuğu fazla miktarda HCl ile tepkimeye sokulduğunda CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂ tepkimesiyle 0,836 g CO₂ çıkıyor. Kabuktaki CaCO₃\'ün kütlece yüzdesi kaçtır? (CaCO₃ = 100, CO₂ = 44 g/mol)', '95', ['42', '84', '19'], '0,836 / 44 = 0,019 mol CO₂ ve aynı mol sayıda CaCO₃ (1,9 g) vardır. 1,9 / 2,0 × 100 = %95.'),
  ('Evlerde kullanılan 12 kg\'lık bir tüpteki gazın tamamının propan (C₃H₈) olduğu varsayılıyor. Tüpteki gaz tamamen yandığında kaç kg CO₂ oluşur? (C = 12, H = 1, O = 16)', '36', ['12', '24', '44'], '12 kg propan = 12/44 kmol\'dür ve her mol 3 mol CO₂ verir: (12/44) × 3 × 44 = 36 kg.'),
  ('Mg + 2HCl → MgCl₂ + H₂ tepkimesinde 0,2 mol Mg ile 0,3 mol HCl kullanılıyor ve 0,12 mol H₂ toplanıyor. Tepkimenin yüzde verimi kaçtır?', '80', ['60', '40', '100'], '0,3 mol HCl ancak 0,15 mol Mg ile tepkimeye girer; HCl sınırlayıcıdır ve kuramsal H₂ 0,15 mol\'dür. 0,12 / 0,15 × 100 = %80.'),
  ('2A → B tepkimesi %60 verimle gerçekleşiyor. 0,3 mol B elde etmek için en az kaç mol A kullanılmalıdır?', '1,0', ['0,6', '0,36', '0,5'], '%60 verimle 0,3 mol B için kuramsal olarak 0,3 / 0,6 = 0,5 mol B gerekir. Bu da 2 × 0,5 = 1,0 mol A demektir.'),
  ('Yan tepkime oluşmadan %75 verimle gerçekleşen bir tepkimede, sınırlayıcı bileşenin yüzde kaçı tepkime sonunda dönüşmeden kalır?', '25', ['75', '0', '50'], 'Yan tepkime yoksa ürüne dönüşmeyen sınırlayıcı bileşen tepkimeye girmemiş demektir. %75\'i dönüştüğüne göre %25\'i kalır.'),
  ('Fe₂O₃ + 3CO → 2Fe + 3CO₂ tepkimesinde 32 g Fe₂O₃ ile 0,9 mol CO kullanılıyor ve 16,8 g demir elde ediliyor. Yüzde verim kaçtır? (Fe = 56, O = 16)', '75', ['50', '56', '84'], 'Fe₂O₃ 0,2 mol olup 0,6 mol CO ister; Fe₂O₃ sınırlayıcıdır. Kuramsal demir 0,4 mol = 22,4 g; 16,8 / 22,4 × 100 = %75.'),
  ('Kütlece %46,7 azot ve %53,3 oksijen içeren bir azot oksidin basit formülü hangisidir? (N = 14, O = 16)', 'NO', ['N₂O', 'NO₂', 'N₂O₃'], 'N: 46,7/14 ≈ 3,33; O: 53,3/16 ≈ 3,33. Mol oranı 1 : 1 olduğundan basit formül NO\'dur.'),
  ('Meyve kokulu bir esterin analizinde kütlece %54,5 C, %9,1 H ve %36,4 O bulunuyor. Bileşiğin basit formülü hangisidir? (C = 12, H = 1, O = 16)', 'C₂H₄O', ['CH₂O', 'C₃H₆O', 'C₄H₄O₂'], 'C: 54,5/12 ≈ 4,54; H: 9,1; O: 36,4/16 ≈ 2,28. En küçüğe bölünce 2 : 4 : 1 elde edilir; basit formül C₂H₄O\'dur.'),
  ('"Aptal altını" olarak bilinen bir demir sülfür minerali kütlece %46,7 Fe ve %53,3 S içerir. Mineralin formülü hangisidir? (Fe = 56, S = 32)', 'FeS₂', ['FeS', 'Fe₂S₃', 'Fe₃S₄'], 'Fe: 46,7/56 ≈ 0,83; S: 53,3/32 ≈ 1,67. Oran 1 : 2 olduğundan formül FeS₂\'dir (pirit).'),
  ('Klorun doğal izotopları ³⁵Cl (34,97 u) ve ³⁷Cl (36,97 u) olup elementin ortalama atom kütlesi 35,45 u\'dur. Doğal klorda ³⁵Cl izotopunun bolluğu yaklaşık yüzde kaçtır?', '76', ['24', '50', '62'], 'x bollukla x(34,97) + (1 − x)(36,97) = 35,45 yazılırsa x = 0,76 bulunur; ³⁵Cl yaklaşık %76 oranındadır.'),
  ('Doğal lityum yaklaşık %7,5 ⁶Li ve %92,5 ⁷Li içerir. Kütle numaralarını atom kütlesi yerine kullanarak ortalama atom kütlesini tahmin edin. Sonuç yaklaşık kaçtır?', '6,9', ['6,5', '6,1', '7,1'], '0,075 × 6 + 0,925 × 7 = 6,925 ≈ 6,9 olur. Değer ağır izotopa daha yakındır çünkü bolluğu çok yüksektir.'),
  ('Yoğunluğu 0,79 g/mL olan etanolün (C₂H₅OH, 46 g/mol) 23 mL\'sinde yaklaşık kaç mol etanol bulunur?', '0,4', ['0,8', '0,2', '1,0'], 'Kütle = 0,79 × 23 ≈ 18,2 g; mol sayısı 18,2 / 46 ≈ 0,4 olur.'),
  ('Aşağıdaki örneklerden hangisi en çok sayıda atom içerir? (Tümü saf maddedir.)', '0,5 mol CH₄', ['0,3 mol C₂H₆', '0,4 mol NH₃', '0,6 mol H₂O'], 'Atom mol sayıları: CH₄ 0,5 × 5 = 2,5; C₂H₆ 0,3 × 8 = 2,4; NH₃ 0,4 × 4 = 1,6; H₂O 0,6 × 3 = 1,8. En büyük değer CH₄\'ündür.'),
  ('Açık bir kapta 10 g CaCO₃ kuvvetle ısıtılıyor ve kapta geriye 5,6 g katı kalıyor. Bu durum kütlenin korunumu yasasıyla nasıl açıklanır?', 'Ayrışmada çıkan 4,4 g CO₂ gazı ortamdan ayrılmıştır.', ['Isıtma sırasında kütlenin bir kısmı enerjiye dönüşmüştür.', 'Kütlenin korunumu yasası açık kaplarda geçerli değildir.', 'CaCO₃\'ün bir kısmı tepkimeye girmeden buharlaşmıştır.'], 'CaCO₃ → CaO + CO₂ tepkimesinde 0,1 mol CO₂ (4,4 g) kaptan çıkar; 10 − 4,4 = 5,6 g katı kalır. Toplam kütle sistem kapalı düşünülünce korunur.'),
  ('Aynı sıcaklık ve basınçta 10 mL NO ile 10 mL O₂ karıştırılıp 2NO + O₂ → 2NO₂ tepkimesi tamamlanıyor. Kaptaki toplam gaz hacmi kaç mL olur?', '15', ['20', '10', '25'], '10 mL NO, 5 mL O₂ ile birleşip 10 mL NO₂ verir; 5 mL O₂ artar. Toplam hacim 10 + 5 = 15 mL\'dir.'),
  ('Gübre olarak kullanılan amonyum sülfatta, (NH₄)₂SO₄, azotun kütlece yüzdesi yaklaşık kaçtır? (H = 1, N = 14, O = 16, S = 32)', '21,2', ['10,6', '42,4', '14,0'], 'Mol kütlesi 132 g/mol; iki N atomu 28 g\'dır. 28 / 132 × 100 ≈ %21,2 bulunur.'),
  ('Kütlece %85,7 karbon ve %14,3 hidrojen içeren bir hidrokarbonun mol kütlesi 56 g/mol\'dür. Molekül formülü nedir? (C = 12, H = 1)', 'C₄H₈', ['C₂H₄', 'C₃H₆', 'C₅H₁₀'], 'C : H mol oranı 7,14 : 14,3 = 1 : 2 olduğundan basit formül CH₂\'dir (14 g/mol). 56 / 14 = 4 olduğundan formül C₄H₈\'dir.'),
  ('0,1 mol bir hidrokarbon oksijende tam yandığında 0,4 mol CO₂ ve 0,5 mol H₂O oluşuyor. Hidrokarbonun formülü nedir?', 'C₄H₁₀', ['C₄H₈', 'C₅H₁₀', 'C₃H₈'], '1 mol hidrokarbon 4 mol CO₂ ve 5 mol H₂O verir; C atomları 4, H atomları 5 × 2 = 10 olur. Formül C₄H₁₀\'dur.'),
  ('Glauber tuzu olarak bilinen Na₂SO₄·10H₂O kristalinde kristal suyunun kütlece yüzdesi yaklaşık kaçtır? (Na = 23, S = 32, O = 16, H = 1)', '56', ['44', '31', '10'], 'Mol kütlesi 142 + 180 = 322 g/mol; 10 H₂O kütlesi 180 g\'dır. 180 / 322 × 100 ≈ %56\'dır.'),
  ('Cu + HNO₃(derişik) → Cu(NO₃)₂ + NO₂ + H₂O tepkimesi en küçük tam sayılarla denkleştirildiğinde HNO₃\'ün katsayısı kaç olur?', '4', ['2', '3', '6'], 'Cu + 4HNO₃ → Cu(NO₃)₂ + 2NO₂ + 2H₂O. Dört HNO₃\'ün ikisi nitrat olarak tuzda, ikisi NO₂\'ye indirgenerek kalır.'),
  ('Na₂SO₄ ve BaCl₂ çözeltileri karıştırıldığında beyaz bir çökelek oluşuyor. Net iyon denklemi hangisidir?', 'Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(k)', ['Na⁺(aq) + Cl⁻(aq) → NaCl(k)', 'Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₃(k)', '2Na⁺(aq) + SO₄²⁻(aq) → Na₂SO₄(k)'], 'Na⁺ ve Cl⁻ seyirci iyonlardır. Çökeleği yalnız Ba²⁺ ve SO₄²⁻ iyonları oluşturur; net denklemde yük ve atom sayıları denktir.'),
  ('16,8 g NaHCO₃ kuvvetle ısıtılarak 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O tepkimesiyle tamamen ayrıştırılıyor. Geriye kalan katının kütlesi kaç gramdır? (Na = 23, H = 1, C = 12, O = 16)', '10,6', ['8,4', '5,3', '16,8'], '16,8 / 84 = 0,2 mol NaHCO₃ → 0,1 mol Na₂CO₃. Kütle 0,1 × 106 = 10,6 g\'dır.'),
  ('5,4 g alüminyum fazla HCl ile 2Al + 6HCl → 2AlCl₃ + 3H₂ tepkimesine göre çözünüyor. Normal koşullarda kaç litre H₂ gazı oluşur? (Al = 27)', '6,72', ['4,48', '3,36', '13,44'], '5,4 / 27 = 0,2 mol Al, 0,3 mol H₂ verir. Hacim 0,3 × 22,4 = 6,72 L olur.'),
  ('14 g demir ile 10 g kükürt Fe + S → FeS tepkimesine göre tam verimle tepkimeye sokuluyor. Tepkime sonunda hangi madde ve kaç gram artar? (Fe = 56, S = 32)', 'Kükürt, 2 g', ['Demir, 2 g', 'Kükürt, 4 g', 'Demir, 4 g'], '0,25 mol Fe ve 0,3125 mol S vardır; Fe sınırlayıcıdır. 0,0625 mol S artar: 0,0625 × 32 = 2 g.'),
  ('Aspirin sentezinde 2,76 g salisilik asitten (138 g/mol) kuramsal olarak 3,6 g aspirin (180 g/mol) elde edilebilmektedir. Deneyde 2,16 g aspirin ayrılırsa yüzde verim kaçtır?', '60', ['50', '75', '80'], 'Yüzde verim = gerçek / kuramsal × 100 = 2,16 / 3,6 × 100 = 60\'tır. 1 mol asit 1 mol aspirin verir; 0,02 mol × 180 = 3,6 g kuramsaldır.'),
  ('Bir çay kaşığı şeker yaklaşık 5,0 g sakkaroz (C₁₂H₂₂O₁₁, 342 g/mol) içerir. Bu miktarda yaklaşık kaç tane karbon atomu bulunur? (NA = 6,02 × 10²³ mol⁻¹)', '1,1 × 10²³', ['8,8 × 10²¹', '1,3 × 10²²', '6,0 × 10²³'], '5,0 / 342 ≈ 0,0146 mol sakkaroz; her molekülde 12 C vardır, 0,175 mol C atomu bulunur. 0,175 × 6,02 × 10²³ ≈ 1,1 × 10²³.'),
  ('Bir kurşun kalemle çizilen çizgide yaklaşık 0,12 mg karbon (C = 12 g/mol) bırakıldığı varsayılırsa çizgide kaç karbon atomu vardır? (NA = 6,02 × 10²³ mol⁻¹)', '6,0 × 10¹⁸', ['6,0 × 10²⁰', '6,0 × 10²³', '7,2 × 10¹⁹'], '0,12 mg = 1,2 × 10⁻⁴ g; n = 1,2 × 10⁻⁴ / 12 = 10⁻⁵ mol. Atom sayısı 10⁻⁵ × 6,02 × 10²³ ≈ 6,0 × 10¹⁸ bulunur.'),
  ('9,2 g etanol (C₂H₅OH, 46 g/mol) oksijende tamamen yakılıyor. C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O tepkimesine göre kaç gram su oluşur? (H = 1, O = 16)', '10,8', ['5,4', '16,2', '21,6'], '9,2 / 46 = 0,2 mol etanol 0,6 mol H₂O verir. Kütle 0,6 × 18 = 10,8 g\'dır.'),
  ('2 g kalsiyum (40 g/mol) ile 0,9 g su (18 g/mol) Ca + 2H₂O → Ca(OH)₂ + H₂ tepkimesine göre karıştırılıyor. Oluşan H₂ kaç moldür?', '0,025', ['0,05', '0,10', '0,0125'], '0,05 mol Ca için 0,10 mol su gerekir ancak 0,05 mol su vardır; su sınırlayıcıdır. 0,05 mol sudan 0,025 mol H₂ oluşur.'),
  ('Mayalanmada C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ tepkimesi gerçekleşir. 90 g glikozun tamamı dönüşürse kaç gram etanol oluşur? (C = 12, H = 1, O = 16)', '46', ['23', '92', '90'], '90 / 180 = 0,5 mol glikoz 1 mol etanol verir. Kütle 1 × 46 = 46 g\'dır.'),
  ('Bakır cevheri kalkositten Cu₂S + O₂ → 2Cu + SO₂ tepkimesiyle bakır elde ediliyor. 1,6 kg Cu₂S\'den kaç kg bakır üretilebilir? (Cu = 64, S = 32)', '1,28', ['0,64', '2,56', '0,80'], '1600 / 160 = 10 mol Cu₂S 20 mol Cu verir. 20 × 64 = 1280 g = 1,28 kg\'dır.'),
  ('Üç basamaklı bir sentezde basamak verimleri sırasıyla %90, %80 ve %50\'dir. Başlangıç maddesinden son ürüne toplam verim yüzde kaçtır?', '36', ['73', '40', '50'], 'Verimler çarpılır: 0,90 × 0,80 × 0,50 = 0,36. Toplam verim %36\'dır; ortalama alınması yanlıştır.'),
  ('Mg₃N₂ + H₂O → Mg(OH)₂ + NH₃ tepkimesi en küçük tam sayılarla denkleştirilirse katsayıların toplamı kaç olur?', '12', ['9', '10', '14'], 'Mg₃N₂ + 6H₂O → 3Mg(OH)₂ + 2NH₃. Toplam 1 + 6 + 3 + 2 = 12\'dir.'),
  ('Asidik ortamda Fe²⁺ + MnO₄⁻ → Fe³⁺ + Mn²⁺ tepkimesinde bir MnO₄⁻ iyonu kaç Fe²⁺ iyonunu yükseltger?', '5', ['2', '3', '7'], 'Mn +7\'den +2\'ye iner, 5 elektron alır. Her Fe²⁺ 1 elektron verdiği için 5 Fe²⁺ yükseltgenir.'),
  ('Cr₂O₇²⁻ + 14H⁺ + ne⁻ → 2Cr³⁺ + 7H₂O yarı tepkimesinde yükün korunması için n kaç olmalıdır?', '6', ['3', '7', '14'], 'Sol tarafın yükü −2 + 14 − n, sağ tarafınki +6\'dır. −2 + 14 − n = 6 eşitliğinden n = 6 bulunur.'),
  ('Bir öğrenci 0,0250 g NaCl\'yi tartıp mol sayısını 0,0250 / 58,5 işlemiyle hesaplıyor. Veriler üç anlamlı rakamlı olduğuna göre sonuç hangi biçimde verilmelidir?', '4,27 × 10⁻⁴ mol', ['4,3 × 10⁻⁴ mol', '4,274 × 10⁻⁴ mol', '4 × 10⁻⁴ mol'], 'Bölmede sonuç, en az anlamlı rakamlı verinin sayısı kadar rakam taşır. İki veri de üç rakamlıdır; 4,2735 × 10⁻⁴ → 4,27 × 10⁻⁴.'),
  ('4,8 g magnezyum tamamen Mg²⁺ iyonuna yükseltgenirken kaç elektron verir? (Mg = 24, NA = 6 × 10²³ mol⁻¹)', '2,4 × 10²³', ['1,2 × 10²³', '4,8 × 10²³', '1,2 × 10²⁴'], '4,8 / 24 = 0,2 mol Mg; her atom 2 elektron verir, 0,4 mol elektron elde edilir. 0,4 × 6 × 10²³ = 2,4 × 10²³.'),
  ('4NH₃ + 5O₂ → 4NO + 6H₂O tepkimesinde 1,2 mol su oluştuğuna göre kaç mol O₂ harcanmıştır?', '1', ['1,5', '0,8', '6'], 'O₂ : H₂O katsayı oranı 5 : 6\'dır. 1,2 × 5/6 = 1 mol O₂ harcanır.'),
  ('Çinko ile kükürt ZnS oluştururken Zn/S kütle oranı 65/32\'dir. 13 g Zn ile 10 g S tepkimeye sokulursa en çok kaç gram ZnS oluşur?', '19,4', ['22,75', '13', '16,2'], '13 g Zn için 6,4 g S gerekir; S artar (3,6 g). Çinko sınırlayıcı olduğundan ZnS = 13 + 6,4 = 19,4 g\'dır.'),
  ('Aynı sıcaklık ve basınçta 20 mL etilen (C₂H₄) yeterli oksijenle tam yakılıyor. C₂H₄ + 3O₂ → 2CO₂ + 2H₂O(g) tepkimesine göre oluşan gazların toplam hacmi kaç mL olur?', '80', ['40', '60', '100'], 'Gazlarda hacim oranı mol oranına eşittir. 20 mL C₂H₄ → 40 mL CO₂ + 40 mL su buharı = 80 mL.'),
  ('2,38 g CoCl₂·xH₂O ısıtılarak tüm kristal suyu uzaklaştırıldığında 1,30 g susuz CoCl₂ kalıyor. x değeri kaçtır? (CoCl₂ = 130 g/mol, H₂O = 18 g/mol)', '6', ['4', '5,5', '7'], 'Su kütlesi 2,38 − 1,30 = 1,08 g, yani 0,06 mol. Susuz tuz 0,01 mol\'dür; oran 0,06 / 0,01 = 6\'dır.'),
  ('Magnezyum şerit seyreltik HCl çözeltisine atıldığında köpürme gözleniyor. Bu olayın net iyon denklemi hangisidir?', 'Mg(k) + 2H⁺(aq) → Mg²⁺(aq) + H₂(g)', ['Mg(k) + 2Cl⁻(aq) → MgCl₂(k)', 'Mg(k) + H⁺(aq) → Mg²⁺(aq) + H₂(g)', 'Mg²⁺(aq) + 2Cl⁻(aq) → MgCl₂(aq)'], 'Cl⁻ seyirci iyondur. Net denklemde atom sayıları ve yükler denk olmalıdır: soldaki 2+ yük sağdaki Mg²⁺ ile eşleşir.'),
  ('Katotta 10,8 g gümüş biriktirmek için AgNO₃ çözeltisinden kaç coulomb yük geçirilmelidir? (Ag = 108, Faraday sabiti ≈ 96 500 C/mol)', '9650', ['96 500', '4825', '19 300'], '10,8 / 108 = 0,1 mol Ag; Ag⁺ + e⁻ → Ag olduğundan 0,1 mol elektron gerekir. Yük 0,1 × 96 500 = 9650 C\'dir.'),
  ('Bir demir cevheri örneğindeki demir, Fe(OH)₃ olarak çöktürülüp yakılarak 0,80 g Fe₂O₃ hâline getiriliyor. Örnekte kaç gram demir vardır? (Fe = 56, O = 16)', '0,56', ['0,80', '0,028', '1,12'], '0,80 / 160 = 0,005 mol Fe₂O₃; her birinde 2 Fe olduğundan 0,01 mol Fe vardır. 0,01 × 56 = 0,56 g.'),
  ('Denizaltılarda hava yenilemede 2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂ tepkimesinden yararlanılır. 7,8 g Na₂O₂ tamamen tepkimeye girerse kaç gram O₂ açığa çıkar? (Na = 23, O = 16)', '1,6', ['3,2', '0,8', '7,8'], '7,8 / 78 = 0,1 mol Na₂O₂ ve katsayı oranı 2 : 1 olduğundan 0,05 mol O₂ oluşur. Kütle 0,05 × 32 = 1,6 g\'dır.'),
  ('1 mol H₂SO₄ ile 1 mol H₂O karşılaştırıldığında hangisi doğrudur?', 'Molekül sayıları eşit, toplam atom sayıları farklıdır.', ['Atom sayıları eşit, molekül sayıları farklıdır.', 'Her ikisinde de aynı sayıda oksijen atomu bulunur.', 'Kütleleri eşit, molekül sayıları farklıdır.'], 'Her iki örnek de NA tane molekül içerir. H₂SO₄ molekülü 7, H₂O molekülü 3 atomludur; atom sayıları ve kütleler farklıdır.'),
  ('Kütlece %20\'si safsızlık olan 50 g kireç taşı fazla HCl ile tepkimeye giriyor. Safsızlıkların tepkimeye girmediği varsayılırsa CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂ tepkimesinde normal koşullarda kaç L CO₂ oluşur? (Ca = 40, C = 12, O = 16)', '8,96', ['11,2', '17,92', '22,4'], 'Saf CaCO₃ kütlesi 50 × 0,80 = 40 g = 0,4 mol; 0,4 mol CO₂ oluşur. Hacim 0,4 × 22,4 = 8,96 L\'dir.'),
  ('Pirit (FeS₂) cevherinden kükürt dioksit, ondan da sülfürik asit üretiliyor. Her S atomunun H₂SO₄\'e dönüştüğü ve verimin %100 olduğu varsayılırsa 120 g saf FeS₂\'den kaç gram H₂SO₄ elde edilir? (Fe = 56, S = 32, H = 1, O = 16)', '196', ['1176', '120', '392'], '120 g FeS₂ = 1 mol ve 2 mol S içerir. 2 mol H₂SO₄ oluşur; kütle 2 × 98 = 196 g\'dır.'),
  ('1\'er gram C, H₂ ve CH₄ oksijende tam yakıldığında en çok oksijen gazı hangisinin yanmasında harcanır? (C = 12, H = 1)', 'H₂', ['C', 'CH₄', 'Üçünde de eşit'], 'Harcanan O₂: C için 1/12 ≈ 0,083 mol; H₂ için 0,5/2 = 0,25 mol; CH₄ için 2/16 = 0,125 mol. En çok O₂ H₂ için gerekir.'),
  ('0,2 mol NH₄⁺ iyonunda toplam kaç mol elektron bulunur?', '2,0', ['2,2', '1,8', '0,20'], 'NH₄⁺ iyonunda elektron sayısı 7 + 4 − 1 = 10\'dur. 0,2 × 10 = 2,0 mol elektron vardır.'),
  ('Altının yoğunluğu 19,3 g/cm³ ve mol kütlesi 197 g/mol\'dür. 1 cm³ saf altında yaklaşık kaç tane atom bulunur? (NA = 6,02 × 10²³ mol⁻¹)', '5,9 × 10²²', ['5,9 × 10²⁴', '3,12 × 10²³', '1,2 × 10²¹'], 'Kütle 19,3 g; n = 19,3 / 197 ≈ 0,098 mol. Atom sayısı 0,098 × 6,02 × 10²³ ≈ 5,9 × 10²².'),
  ('Bir tuz tanesinin kütlesi yaklaşık 0,06 mg\'dır. Tane saf NaCl ise yaklaşık kaç formül birimi içerir? (NaCl = 58,5 g/mol, NA = 6,02 × 10²³ mol⁻¹)', '6 × 10¹⁷', ['6,02 × 10²⁰', '1 × 10⁻⁶', '6 × 10¹⁴'], '0,06 mg = 6 × 10⁻⁵ g; n = 6 × 10⁻⁵ / 58,5 ≈ 1,0 × 10⁻⁶ mol. Formül birimi sayısı yaklaşık 6 × 10¹⁷\'dir.'),
  ('Müshil olarak kullanılan Epsom tuzu MgSO₄·7H₂O formülüne sahiptir. Kristal suyunun kütlece yüzdesi yaklaşık kaçtır? (Mg = 24, S = 32, O = 16, H = 1)', '51,2', ['0,512', '14,6', '71,4'], 'Mol kütlesi 120 + 126 = 246 g/mol; yedi su molekülü 126 g\'dır. 126 / 246 × 100 ≈ %51,2.'),
  ('C₈H₁₀N₄O₂ formülüne sahip kafeinde azotun kütlece yüzdesi yaklaşık kaçtır? (H = 1, C = 12, N = 14, O = 16)', '28,9', ['0,289', '7,2', '57,7'], 'Mol kütlesi 96 + 10 + 56 + 32 = 194 g/mol\'dür. Azot 56 g\'dır; 56 / 194 × 100 ≈ %28,9.'),
  ('Bir öğrenci \'H₂ + O₂ → H₂O\' denklemine bakarak 1 mol H₂ ile 1 mol O₂\'nin artansız tepkimeye gireceğini düşünüyor. Doğru denkleştirilmiş denkleme göre tam verimle tepkime sonunda kapta ne kalır?', 'Su ve 0,5 mol O₂', ['Yalnız su', 'Su ve 0,5 mol H₂', 'Su ve 1 mol O₂ ile birlikte 1 mol H₂'], 'Doğru denklem 2H₂ + O₂ → 2H₂O\'dur. 1 mol H₂ yalnız 0,5 mol O₂ ile birleşir; 1 mol su oluşur ve 0,5 mol O₂ artar.'),
  ('Lavoisier\'in ünlü deneyindeki gibi 43,3 g civa(II) oksit, 2HgO → 2Hg + O₂ tepkimesiyle tamamen ayrıştırılıyor. Açığa çıkan oksijenin kütlesi kaç gramdır? (Hg = 200,6, O = 16)', '3,2', ['1,6', '6,4', '43,3'], '43,3 / 216,6 ≈ 0,2 mol HgO; katsayı oranı 2 : 1 olduğundan 0,1 mol O₂ oluşur. Kütle 0,1 × 32 = 3,2 g\'dır.'),
  ('Kükürt, oda koşullarında S₈ molekülleri hâlinde bulunur. 12,8 g kükürt örneği kaç mol S atomu içerir? (S = 32)', '0,4', ['0,05', '1,6', '12,8'], '12,8 g / 32 g/mol = 0,4 mol S atomudur. Molekül sayısı bakımından bu 0,05 mol S₈\'e karşılık gelir; ancak atom mol sayısı sorulmuştur.'),
  ('4,8 g ozon (O₃) gazında kaç tane oksijen atomu bulunur? (O = 16, NA = 6 × 10²³ mol⁻¹)', '1,8 × 10²³', ['6,0 × 10²²', '3,6 × 10²³', '9,03 × 10²³'], '4,8 / 48 = 0,1 mol O₃ ve her molekülde 3 atom vardır. 0,3 mol atom × 6 × 10²³ = 1,8 × 10²³.'),
  ('16 g O₂ ve 16 g O₃ örnekleri karşılaştırıldığında hangisi doğrudur? (O = 16)', 'Atom sayıları eşittir, molekül sayıları farklıdır.', ['Molekül sayıları eşittir, atom sayıları farklıdır.', 'Hem atom hem de molekül sayıları birbirine eşittir.', 'O₃ örneği daha fazla atom içerir.'], 'İkisi de yalnız oksijen atomlarından oluştuğundan 16 g oksijen 1 mol atom içerir. O₂ örneğinde 0,5 mol, O₃ örneğinde 1/3 mol molekül vardır.'),
  ('0,1 mol CuSO₄·5H₂O kristalinde toplam kaç mol atom bulunur?', '2,1', ['0,6', '1,5', '2,60'], 'Bir formül biriminde CuSO₄\'ten 6, beş su molekülünden 15 atom olmak üzere 21 atom vardır. 0,1 × 21 = 2,1 mol.'),
  ('Roket yakıtı olarak hidrazin kullanılan N₂H₄ + O₂ → N₂ + 2H₂O tepkimesinde 6,4 g hidrazin tam yanarsa kaç gram su oluşur? (N = 14, H = 1, O = 16)', '7,2', ['3,6', '14,4', '6,4'], '6,4 / 32 = 0,2 mol N₂H₄ 0,4 mol H₂O verir. Kütle 0,4 × 18 = 7,2 g\'dır.'),
  ('Bir kireç taşı örneğindeki kalsiyum, CaC₂O₄ olarak çöktürülüp ısıtılarak CaO\'ya dönüştürülüyor ve 0,28 g CaO tartılıyor. Örnekte kaç gram kalsiyum vardır? (Ca = 40, O = 16)', '0,20', ['0,28', '0,14', '0,056'], '0,28 / 56 = 0,005 mol CaO ve her birinde bir Ca vardır. 0,005 × 40 = 0,20 g kalsiyum bulunur.'),
  ('Bir hücre kültürü dakikada 0,02 mol CO₂ üretiyor. Bir saatte üretilen CO₂ kütlesi kaç gramdır? (C = 12, O = 16)', '52,8', ['0,88', '2,64', '1320,0'], '1 saatte 0,02 × 60 = 1,2 mol CO₂ oluşur. Kütle 1,2 × 44 = 52,8 g\'dır.'),
  ('Karbon (12,01 g/mol) ve hidrojen (1,008 g/mol) değerleriyle metanın mol kütlesi hesaplanırken toplamada sonuç hangi biçimde verilmelidir?', '16,04 g/mol', ['16,042 g/mol', '16,0 g/mol', '16 g/mol'], 'Toplama ve çıkarmada sonuç, en az ondalık basamaklı verinin basamak sayısını taşır. 12,01 iki basamaklı olduğundan 16,042 → 16,04 olur.'),
  ('Kapta 5 tane A₂ ve 6 tane B₂ molekülü vardır. A₂ + 3B₂ → 2AB₃ tepkimesi tam verimle gerçekleştiğinde kapta toplam kaç molekül bulunur?', '7', ['5', '9', '11'], '6 B₂ molekülü 2 A₂ ile birleşip 4 AB₃ oluşturur. 3 A₂ artar; toplam 4 + 3 = 7 molekül vardır.'),
  ('Fe³⁺ iyonlarının Sn²⁺ iyonlarıyla Fe²⁺ ve Sn⁴⁺ oluşturduğu tepkimenin atom ve yük bakımından denk yazılmış hâli hangisidir?', '2Fe³⁺ + Sn²⁺ → 2Fe²⁺ + Sn⁴⁺', ['Fe³⁺ + Sn²⁺ → Fe²⁺ + Sn⁴⁺', 'Fe³⁺ + 2Sn²⁺ → Fe²⁺ + 2Sn⁴⁺', '2Fe³⁺ + 2Sn²⁺ → 2Fe²⁺ + Sn⁴⁺'], 'Sn²⁺ iki elektron verirken Fe³⁺ birer elektron alır; bu nedenle 2 Fe³⁺ gerekir. Her iki tarafta toplam yük +8\'dir.'),
  ('Bir tepkimede %72 verimle 18 g ürün elde edilmiştir. Aynı tepkimenin kuramsal verimi kaç gram ürünle sonuçlanırdı?', '25', ['13', '18', '32,4'], 'Gerçek verim = kuramsal verim × 0,72 olduğundan kuramsal verim 18 / 0,72 = 25 g\'dır.'),
  ('Bir kuru pilde 0,65 g çinko Zn²⁺ iyonuna yükseltgeniyor. Devreden geçen toplam yük kaç coulomb olur? (Zn = 65, Faraday sabiti ≈ 96 500 C/mol)', '1930', ['965', '3860', '96 500'], '0,65 / 65 = 0,01 mol Zn; Zn → Zn²⁺ + 2e⁻ olduğundan 0,02 mol elektron geçer. Yük 0,02 × 96 500 = 1930 C\'dir.'),
  ('2N₂O₅ → 4NO₂ + O₂ tepkimesinde 0,5 mol N₂O₅ tamamen ayrışırsa oluşan gazların toplam mol sayısı kaç olur?', '1,25', ['0,75', '1,0', '2,500'], '0,5 mol N₂O₅ 1,0 mol NO₂ ve 0,25 mol O₂ verir. Toplam gaz 1,25 mol\'dür.'),
  ('Amonyum nitratın patlayıcı ayrışması 2NH₄NO₃ → 2N₂ + O₂ + 4H₂O(g) biçiminde gerçekleşir. 160 g NH₄NO₃ tamamen ayrışırsa oluşan gazların toplam mol sayısı kaçtır? (H = 1, N = 14, O = 16)', '7', ['3,5', '4', '8'], '160 / 80 = 2 mol NH₄NO₃ 2 mol N₂, 1 mol O₂ ve 4 mol H₂O(g) verir. Toplam 2 + 1 + 4 = 7 mol gaz oluşur.'),
  ('0,50 g organik örnek yakıldığında yalnız 0,44 g CO₂ oluştuğu belirleniyor. Örnekte karbonun kütlece yüzdesi kaçtır? (C = 12, O = 16)', '24', ['12', '48', '88,0'], '0,44 / 44 = 0,01 mol CO₂ yani 0,01 mol C; kütlesi 0,12 g\'dır. 0,12 / 0,50 × 100 = %24.'),
  ('Basit formülü C₃H₇ olan bir hidrokarbonun mol kütlesi 86 g/mol\'dür. Molekül formülü nedir? (C = 12, H = 1)', 'C₆H₁₄', ['C₃H₇', 'C₉H₂₁', 'C₄H₁₀'], 'C₃H₇\'nin kütlesi 43 g/mol\'dür; 86 / 43 = 2 olduğundan molekül formülü C₆H₁₄ olur ve doymuş hidrokarbon kuralına da uyar.'),
  ('Suda hidrojen kütlece yaklaşık %11,1 iken atom sayısı bakımından yaklaşık %66,7\'dir. Bu farkın nedeni nedir?', 'Hidrojen atomunun kütlesi oksijeninkinden çok daha küçüktür.', ['Suda hidrojen oksijenle iyonik bağ yapmıştır.', 'Hidrojen atomları suda oksijen atomlarından daha ağırdır.', 'Yüzde bileşim hesabında atom sayısı değil mol kütlesi kullanılmaz.'], 'H₂O\'da 2 H ve 1 O atomu vardır (H atomları 2/3); fakat 2 g hidrojen 16 g oksijenle birlikte olduğundan kütlece 2/18 ≈ %11,1 düşer.'),
  ('Bir demir parçası havada paslanırken 4Fe + 3O₂ → 2Fe₂O₃ tepkimesi gerçekleşir. 11,2 g demirin tamamen paslanması için kaç mol O₂ gerekir? (Fe = 56)', '0,15', ['0,20', '0,30', '0,075'], '11,2 / 56 = 0,2 mol Fe; O₂ : Fe katsayı oranı 3 : 4\'tür. 0,2 × 3/4 = 0,15 mol O₂ gerekir.'),
  ('Bakır cevheri kalkopirit CuFeS₂ formülüyle gösterilir. Bu mineralde bakırın kütlece yüzdesi yaklaşık kaçtır? (S = 32, Fe = 56, Cu = 64)', '34,8', ['17,40', '46,4', '69,6'], 'Mol kütlesi 64 + 56 + 64 = 184 g/mol\'dür. Bakır yüzdesi 64 / 184 × 100 ≈ %34,8.'),
  ('Yeşil renkli malakit minerali Cu₂CO₃(OH)₂ formülüne sahiptir. Bakırın kütlece yüzdesi yaklaşık kaçtır? (H = 1, C = 12, O = 16, Cu = 64)', '57,7', ['28,80', '66,7', '45,0'], 'Mol kütlesi 128 + 12 + 48 + 34 = 222 g/mol\'dür. İki Cu atomu 128 g olduğundan 128 / 222 × 100 ≈ %57,7.'),
  ('Kabartma tozundaki NaHCO₃, 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O tepkimesiyle ısıtıldığında saf örneğin kütlesi yüzde kaç azalır? (H = 1, C = 12, O = 16, Na = 23)', '36,9', ['18,50', '26,2', '63,1'], '2 mol NaHCO₃ (168 g) ısıtılınca 1 mol Na₂CO₃ (106 g) kalır; 62 g kayıp olur. 62 / 168 × 100 ≈ %36,9.'),
  ('Cu ve Zn\'den oluşan 10 g pirinç, fazla HCl\'ye atıldığında yalnız çinko Zn + 2HCl → ZnCl₂ + H₂ tepkimesine girer ve normal koşullarda 1,12 L H₂ açığa çıkar. Pirinçte çinkonun kütlece yüzdesi kaçtır? (Zn = 65)', '32,5', ['16,30', '65,0', '11,2'], '1,12 / 22,4 = 0,05 mol H₂ ve 0,05 mol Zn; kütlesi 3,25 g\'dır. 3,25 / 10 × 100 = %32,5.'),
  ('Kütlece %51\'i Al₂O₃ olan 100 g boksit cevherinden tam verimle en çok kaç gram alüminyum elde edilebilir? (Al = 27, O = 16)', '27', ['13,5', '51', '54'], '51 g Al₂O₃ / 102 = 0,5 mol; her mol 2 mol Al içerdiğinden 1 mol Al vardır. Kütle 27 g\'dır.'),
  ('Kütlece %80 Fe₂O₃ içeren 1 ton hematit cevherindeki demirin tamamı metal olarak elde edilirse kaç kilogram demir üretilir? (Fe = 56, O = 16)', '560', ['800', '280', '1120'], '800 kg Fe₂O₃ = 5 kmol; her kmol\'de 2 kmol Fe vardır. 10 kmol × 56 = 560 kg demir elde edilir.'),
  ('Hücresel solunumda glikozun tam oksidasyonu C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O ile gösterilir. 9 g glikoz tamamen yandığında kaç gram CO₂ oluşur? (C = 12, H = 1, O = 16)', '13,2', ['6,6', '26,40', '44'], '9 / 180 = 0,05 mol glikoz 0,3 mol CO₂ verir. Kütle 0,3 × 44 = 13,2 g\'dır.'),
  ('Bir mide antiasit tabletinde 0,58 g Mg(OH)₂ vardır. Bu tablet, Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O tepkimesine göre en çok kaç milimol HCl\'yi nötrleştirir? (Mg = 24, O = 16, H = 1)', '20', ['10,0', '5', '40'], '0,58 / 58 = 0,01 mol Mg(OH)₂ ve 2 mol HCl nötrler; 0,02 mol = 20 mmol HCl\'dir.'),
  ('Mum yapımında kullanılan parafinin bir bileşeni C₂₅H₅₂\'dir. Tam yanma denklemi en küçük tam sayılarla denkleştirilirse O₂\'nin katsayısı kaç olur?', '38', ['25,0', '26', '76'], 'C₂₅H₅₂ + 38O₂ → 25CO₂ + 26H₂O. Oksijen atomları: 25 × 2 + 26 = 76 olduğundan O₂ katsayısı 76 / 2 = 38\'dir.'),
  ('Asidik ortamda Fe²⁺ + H₂O₂ + H⁺ → Fe³⁺ + H₂O tepkimesi denkleştirildiğinde H⁺ iyonunun katsayısı kaç olur?', '2', ['1,0', '4', '6'], '2Fe²⁺ + H₂O₂ + 2H⁺ → 2Fe³⁺ + 2H₂O. Yük ve atom sayıları denktir: sol +6, sağ +6.'),
  ('0,1 mol fosforik asit (H₃PO₄) molekülünde toplam kaç mol proton bulunur? (Atom numaraları: H = 1, O = 8, P = 15)', '5,0', ['3,20', '4,0', '6,0'], 'Bir H₃PO₄ molekülünde proton sayısı 3 × 1 + 15 + 4 × 8 = 50\'dir. 0,1 × 50 = 5,0 mol proton vardır.'),
  ('3 mikromol (3 µmol) cıva kaç mikrogramdır? (Hg = 200 g/mol)', '600', ['0,6', '66,7', '6 × 10⁸'], '3 × 10⁻⁶ mol × 200 g/mol = 6 × 10⁻⁴ g = 600 µg\'dır.'),
  ('2,0 g su örneğinin mol sayısı, 2,0 g iki anlamlı rakamlı ve H₂O = 18,015 g/mol olarak bölünerek hesaplanıyor. Sonuç anlamlı rakam kuralına göre nasıl yazılmalıdır?', '0,11 mol', ['0,111 mol', '0,1110 mol', '0,1 mol'], 'Bölmede sonuç, en az anlamlı rakamlı veriye (2,0 → iki anlamlı rakam) göre yazılır. 2,0 / 18,015 = 0,1110 → 0,11 mol.'),
  ('0,250 mol CO₂ için kütle, 0,250 × 44,01 işlemiyle bulunuyor. Anlamlı rakam kuralına göre sonuç hangisidir?', '11,0 g', ['11 g', '11,00 g', '11,003 g'], 'Çarpmada sonuç, en az anlamlı rakamlı veri (0,250 → üç rakam) kadar rakam taşır. 11,0025 → 11,0 g.'),
  ('Oda koşullarında 1 mol gazın hacmi 24,5 L kabul edilirse 1,2 g magnezyum fazla asitte çözündüğünde açığa çıkan H₂ gazı kaç litre hacim kaplar? (Mg = 24)', '1,23', ['0,610', '1,12', '2,45'], '1,2 / 24 = 0,05 mol Mg 0,05 mol H₂ verir. Hacim 0,05 × 24,5 ≈ 1,23 L\'dir.'),
  ('Efervesan tabletlerde 3NaHCO₃ + H₃C₆H₅O₇ → Na₃C₆H₅O₇ + 3CO₂ + 3H₂O tepkimesi gerçekleşir. 1,68 g NaHCO₃ yeterli sitrik asitle tepkimeye girerse kaç gram CO₂ çıkar? (Na = 23, H = 1, C = 12, O = 16)', '0,88', ['1,320', '0,44', '2,64'], '1,68 / 84 = 0,02 mol NaHCO₃ ve katsayılar eşit olduğundan 0,02 mol CO₂ oluşur. Kütle 0,02 × 44 = 0,88 g\'dır.'),
  ('8,4 g sodyum bikarbonat ile 3,0 g asetik asit CH₃COOH + NaHCO₃ → CH₃COONa + H₂O + CO₂ tepkimesine göre karıştırılıyor. Açığa çıkan CO₂ kaç gramdır? (Na = 23, H = 1, C = 12, O = 16)', '2,2', ['4,40', '1,1', '3,3'], '0,1 mol NaHCO₃ ve 0,05 mol asetik asit vardır; asit sınırlayıcıdır. 0,05 mol CO₂ oluşur ve 0,05 × 44 = 2,2 g\'dır.'),
  ('Egzoz gazı CO\'nun yanması 2CO + O₂ → 2CO₂ denklemiyle verilir. 11,2 g CO tamamen yanarsa kaç gram O₂ harcanır? (C = 12, O = 16)', '6,4', ['3,2', '12,8', '11,2'], '11,2 / 28 = 0,4 mol CO; O₂ : CO oranı 1 : 2 olduğundan 0,2 mol O₂ harcanır. Kütle 0,2 × 32 = 6,4 g\'dır.'),
  ('XY₂ bileşiğinde X/Y kütle oranı 3/8\'dir. Y\'nin atom kütlesi 16 ise X\'in atom kütlesi kaçtır?', '12', ['6', '24,0', '48'], 'XY₂\'de 2 mol Y 32 g\'dır. X kütlesi 3/8 × 32 = 12 g olduğundan atom kütlesi 12\'dir (bileşik CO₂\'ye uyar).'),
  ('Bir elementin 2 gramında 3,01 × 10²² tane atom bulunuyor. Elementin mol kütlesi kaç g/mol\'dür? (NA = 6,02 × 10²³ mol⁻¹)', '40', ['20,0', '80', '60'], '3,01 × 10²² / 6,02 × 10²³ = 0,05 mol; mol kütlesi 2 g / 0,05 mol = 40 g/mol\'dür.'),
  ('0,1 mol M₂O₃ oksidinin kütlesi 16 g\'dır. M elementinin atom kütlesi kaçtır? (O = 16)', '56', ['32', '112', '27'], 'Mol kütlesi 16 / 0,1 = 160 g/mol\'dür. 2M + 48 = 160 olduğundan M = 56\'dır.'),
  ('Manyetit cevheri Fe₃O₄ karbon monoksitle Fe₃O₄ + 4CO → 3Fe + 4CO₂ tepkimesine göre indirgeniyor. 23,2 g Fe₃O₄\'ten tam verimle kaç gram demir elde edilir? (Fe = 56, O = 16)', '16,8', ['5,6', '11,20', '22,4'], '23,2 / 232 = 0,1 mol Fe₃O₄ 0,3 mol Fe verir. Kütle 0,3 × 56 = 16,8 g\'dır.'),
  ('Suyun elektrolizinde 2H₂O → 2H₂ + O₂ tepkimesi gerçekleşir. 9 g suyun tamamı ayrıştırılırsa normal koşullarda kaç litre O₂ oluşur? (H = 1, O = 16)', '5,6', ['11,2', '2,8', '22,4'], '9 / 18 = 0,5 mol su 0,25 mol O₂ verir. Hacim 0,25 × 22,4 = 5,6 L\'dir.'),
  ('6,2 g beyaz fosfor (P₄) oksijende P₄ + 5O₂ → P₄O₁₀ tepkimesine göre tamamen yakılıyor. Oluşan P₄O₁₀ kaç gramdır? (P = 31, O = 16)', '14,2', ['7,1', '28,40', '6,2'], '6,2 / 124 = 0,05 mol P₄ 0,05 mol P₄O₁₀ verir. Mol kütlesi 124 + 160 = 284 g/mol; kütle 14,2 g\'dır.'),
  ('Eşit kütlelerde alınan CaCO₃ (100 g/mol) ve MgCO₃ (84 g/mol) fazla asitle tepkimeye girerse açığa çıkan CO₂ miktarlarının oranı (MgCO₃ / CaCO₃) yaklaşık kaçtır?', '1,19', ['0,840', '1,00', '1,50'], 'Kütle m olsun: CO₂ mol sayısı MgCO₃ için m/84, CaCO₃ için m/100\'dür. Oran 100 / 84 ≈ 1,19.'),
  ('Aspirin sentezi C₇H₆O₃ (138) + C₄H₆O₃ (102) → C₉H₈O₄ (180) + C₂H₄O₂ (60) tepkimesine dayanır. İstenen ürün aspirin ise atom ekonomisi yüzde kaçtır?', '75', ['60', '83', '100'], 'Girenlerin toplam kütlesi 240 g/mol\'dür. Aspirin 180 g/mol olduğundan atom ekonomisi 180 / 240 × 100 = %75\'tir.'),
  ('1 mg saf NaCl kaç mikromol (µmol) NaCl\'dir? (NaCl = 58,5 g/mol)', '17,1', ['1,71', '58,5', '0,0171'], '1 mg = 10⁻³ g; n = 10⁻³ / 58,5 ≈ 1,71 × 10⁻⁵ mol = 17,1 µmol\'dür.'),
  ('1 mol Na⁺ iyonunun kütlesi ile 1 mol Na atomunun kütlesi yaklaşık olarak eşit alınabilir. Bunun temel nedeni nedir?', 'Elektronun kütlesi atom kütlesine göre ihmal edilebilecek kadar küçüktür.', ['İyon oluşurken çekirdekten proton ayrılır ve kütle korunur.', 'Na⁺ iyonunda nötron sayısı elektron sayısıyla aynı kalır.', 'Mol kütlesi yalnız atom numarasına bağlıdır.'], 'Bir elektronun kütlesi protonun yaklaşık 1/1836\'sıdır. Na atomu bir elektron verince kütle değişimi ihmal edilebilir; 1 mol için fark yaklaşık 0,0005 g\'dır.'),
  ('Alçı taşının bileşenlerinden CaSO₄·2H₂O formülünde kalsiyumun kütlece yüzdesi yaklaşık kaçtır? (H = 1, O = 16, S = 32, Ca = 40)', '23,3', ['11,60', '29,4', '46,5'], 'Mol kütlesi 136 + 36 = 172 g/mol\'dür. Kalsiyum yüzdesi 40 / 172 × 100 ≈ %23,3.'),
  ('Bir çay bardağındaki 200 g su yaklaşık kaç tane H₂O molekülü içerir? (H₂O = 18 g/mol, NA = 6,02 × 10²³ mol⁻¹)', '6,7 × 10²⁴', ['6,7 × 10²²', '3,3 × 10²⁵', '1,2 × 10²⁶'], '200 / 18 ≈ 11,1 mol su; molekül sayısı 11,1 × 6,02 × 10²³ ≈ 6,7 × 10²⁴ bulunur.'),
  ('70 kg kütleli bir insanın %60\'ının su olduğu varsayılırsa vücutta yaklaşık kaç mol su bulunur? (H₂O = 18 g/mol)', '2,3 × 10³', ['2,3 × 10²', '4,2 × 10⁴', '3,9 × 10³'], 'Su kütlesi 70 × 0,60 = 42 kg = 42 000 g; n = 42 000 / 18 ≈ 2333 mol ≈ 2,3 × 10³ mol\'dür.'),
  ('Bir karat (0,2 g) ağırlığındaki saf elmas yaklaşık kaç karbon atomu içerir? (C = 12, NA = 6,02 × 10²³ mol⁻¹)', '1,0 × 10²²', ['1,0 × 10²⁰', '6,0 × 10²³', '2,4 × 10²⁴'], '0,2 / 12 ≈ 0,0167 mol C; atom sayısı 0,0167 × 6,02 × 10²³ ≈ 1,0 × 10²².'),
  ('Doğal gazdaki H₂S, 2H₂S + 3O₂ → 2SO₂ + 2H₂O tepkimesiyle yakılıyor. 6,8 g H₂S tamamen yandığında kaç gram SO₂ oluşur? (H = 1, S = 32, O = 16)', '12,8', ['6,4', '25,60', '6,8'], '6,8 / 34 = 0,2 mol H₂S 0,2 mol SO₂ verir. Kütle 0,2 × 64 = 12,8 g\'dır.'),
  ('33,1 g Pb(NO₃)₂ ısıtıldığında 2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂ tepkimesiyle tamamen ayrışıyor. Oluşan gazların toplam mol sayısı kaçtır? (Pb = 207, N = 14, O = 16)', '0,25', ['0,100', '0,45', '0,50'], '33,1 / 331 = 0,1 mol tuz 0,2 mol NO₂ ve 0,05 mol O₂ verir. Toplam gaz 0,25 mol\'dür; PbO katıdır.'),
  ('Havai fişek ve barut yapımında kullanılan KNO₃, 2KNO₃ → 2KNO₂ + O₂ tepkimesiyle ısıtılıyor. 10,1 g KNO₃ tamamen ayrışırsa kaç gram O₂ açığa çıkar? (K = 39, N = 14, O = 16)', '1,6', ['3,20', '0,8', '6,4'], '10,1 / 101 = 0,1 mol KNO₃; O₂ : KNO₃ oranı 1 : 2 olduğundan 0,05 mol O₂ oluşur. Kütle 0,05 × 32 = 1,6 g\'dır.'),
  ('Elektrolizde devreden 1 mol elektron için katotta biriken metal kütleleri karşılaştırılırken aşağıdakilerden hangisi en küçük kütleyi verir? (Ag⁺, Cu²⁺, Zn²⁺, Al³⁺ iyonlarının indirgendiği düşünülsün; Ag = 108, Cu = 64, Zn = 65, Al = 27)', 'Al', ['Ag', 'Cu', 'Zn'], '1 mol elektronla biriken kütle atom kütlesinin değerliğe bölümüdür: Ag 108, Cu 32, Zn 32,5, Al 9 g. En küçük kütle alüminyumdadır.'),
  ('0,5 mol Al₂O₃ katısı tamamen iyonlarına ayrışmış olarak düşünülürse toplam kaç tane iyon içerir? (NA = 6 × 10²³ mol⁻¹)', '1,5 × 10²⁴', ['3,0 × 10²³', '9,0 × 10²³', '3,0 × 10²⁴'], 'Her formül birimi 2 Al³⁺ ve 3 O²⁻ olmak üzere 5 iyon içerir. 0,5 × 5 = 2,5 mol iyon; 2,5 × 6 × 10²³ = 1,5 × 10²⁴.'),
  ('Kütlece %90 karbon içeren 1 kg kömür tamamen yandığında C + O₂ → CO₂ tepkimesine göre yaklaşık kaç kilogram CO₂ oluşur? (C = 12, O = 16)', '3,3', ['1,50', '2,2', '4,4'], '900 g C = 75 mol, 75 mol CO₂ verir. Kütle 75 × 44 = 3300 g = 3,3 kg\'dır.'),
  ('16 g Fe₂O₃ ile 11,2 g CO, Fe₂O₃ + 3CO → 2Fe + 3CO₂ tepkimesine göre tam verimle tepkimeye giriyor. Tepkime sonunda hangi maddeden kaç gram artar? (Fe = 56, C = 12, O = 16)', 'CO, 2,8 g', ['Fe₂O₃, 2,8 g', 'CO, 0,1 g', 'Fe₂O₃, 8 g'], '0,1 mol Fe₂O₃ için 0,3 mol CO gerekir; 0,4 mol CO vardır. 0,1 mol CO artar; kütlesi 2,8 g\'dır.'),
  ('10 g CaCO₃ ile 6 g SiO₂, CaCO₃ + SiO₂ → CaSiO₃ + CO₂ tepkimesine göre tam verimle tepkimeye giriyor. Oluşan CaSiO₃ kaç gramdır? (Ca = 40, Si = 28, C = 12, O = 16)', '11,6', ['16,00', '10', '6'], '10 / 100 = 0,1 mol CaCO₃ ve 6 / 60 = 0,1 mol SiO₂ vardır; ikisi de tamamen harcanır. 0,1 mol CaSiO₃ = 0,1 × 116 = 11,6 g.'),
  ('Benzenin nitrolanmasında C₆H₆ + HNO₃ → C₆H₅NO₂ + H₂O tepkimesi gerçekleşir. 7,8 g benzenden %70 verimle kaç gram nitrobenzen (123 g/mol) elde edilir? (C₆H₆ = 78 g/mol)', '8,61', ['12,30', '17,6', '5,46'], '7,8 / 78 = 0,1 mol benzen kuramsal olarak 12,3 g nitrobenzen verir. %70 verimle 12,3 × 0,70 = 8,61 g elde edilir.'),
  ('Analitik kimyada ayarlı çözeltilerde kullanılan Mohr tuzu, (NH₄)₂Fe(SO₄)₂·6H₂O formülüne sahiptir. Bu hidratın mol kütlesi kaç g/mol\'dür? (H = 1, N = 14, O = 16, S = 32, Fe = 56)', '392', ['284,0', '356', '428'], '(NH₄)₂ için 36, Fe için 56, (SO₄)₂ için 192 ve 6H₂O için 108 g/mol toplanır: 36 + 56 + 192 + 108 = 392 g/mol.'),
  ('Şap olarak bilinen KAl(SO₄)₂·12H₂O hidratında kristal suyunun kütlece yüzdesi yaklaşık kaçtır? (H = 1, O = 16, Al = 27, S = 32, K = 39)', '45,6', ['22,80', '37,9', '54,4'], 'Mol kütlesi 39 + 27 + 192 + 216 = 474 g/mol\'dür. Oniki su molekülü 216 g\'dır; 216 / 474 × 100 ≈ %45,6.'),
  ('Bir takviye ürününün etiketinde 1250 mg CaCO₃ yazıyor. Bu tabletteki elementel kalsiyum kaç miligramdır? (Ca = 40, C = 12, O = 16)', '500', ['1250', '400', '625'], '1,25 g / 100 g/mol = 0,0125 mol CaCO₃ ve aynı miktarda Ca vardır. 0,0125 × 40 = 0,50 g = 500 mg.'),
  ('Demir takviyesi olarak kullanılan bir tablet 325 mg FeSO₄ (152 g/mol) içeriyor. Tabletteki elementel demir yaklaşık kaç miligramdır? (Fe = 56)', '120', ['56', '325,0', '152'], '325 / 152 ≈ 2,14 mmol FeSO₄ ve aynı miktarda Fe vardır. 2,14 × 56 ≈ 120 mg demir bulunur.'),
  ('Kütlece %0,32 NaF içeren 100 g diş macununda yaklaşık kaç miligram flor (F) bulunur? (F = 19, Na = 23)', '145', ['320,0', '19', '42'], '100 g macunda 0,32 g = 320 mg NaF vardır. Florun kütle oranı 19/42 olduğundan 320 × 19/42 ≈ 145 mg flor bulunur.'),
  ('Bir antiasit tabletinde 0,78 g Al(OH)₃ (78 g/mol) vardır. Al(OH)₃ + 3HCl → AlCl₃ + 3H₂O tepkimesine göre tablet en çok kaç milimol HCl\'yi nötrleştirir?', '30', ['10,0', '20', '60'], '0,78 / 78 = 0,01 mol Al(OH)₃ 0,03 mol HCl nötrler. Bu 30 mmol\'dür.'),
  ('Çeliğin sertliğini artıran sementit bileşiği Fe₃C\'dir. Sementitte karbonun kütlece yüzdesi yaklaşık kaçtır? (C = 12, Fe = 56)', '6,67', ['3,330', '12,0', '25,0'], 'Mol kütlesi 3 × 56 + 12 = 180 g/mol\'dür. Karbon yüzdesi 12 / 180 × 100 ≈ %6,67\'dir.'),
  ('5,6 g\'lık bir çelik yünü demirin tamamı paslanarak 4Fe + 3O₂ → 2Fe₂O₃ tepkimesine göre Fe₂O₃\'e dönüşüyor. Kütle artışı kaç gramdır? (Fe = 56, O = 16)', '2,4', ['5,60', '8,0', '1,6'], '5,6 / 56 = 0,1 mol Fe 0,05 mol Fe₂O₃ verir; kütlesi 8,0 g\'dır. Artış 8,0 − 5,6 = 2,4 g, yani bağlanan oksijen kütlesidir.'),
  ('Gümüş takının kararması 4Ag + 2H₂S + O₂ → 2Ag₂S + 2H₂O tepkimesiyle olur. 2,16 g gümüşün tamamı Ag₂S\'e dönüşürse kaç gram Ag₂S oluşur? (Ag = 108, S = 32)', '2,48', ['1,240', '4,96', '2,16'], '2,16 / 108 = 0,02 mol Ag, 0,01 mol Ag₂S verir. Mol kütlesi 248 g/mol; kütle 2,48 g\'dır.'),
  ('Cam üretiminde Na₂CO₃ + SiO₂ → Na₂SiO₃ + CO₂ tepkimesi gerçekleşir. 10,6 g Na₂CO₃ ile 12 g SiO₂ tam verimle tepkimeye girerse kaç gram Na₂SiO₃ oluşur? (Na = 23, Si = 28, C = 12, O = 16)', '12,2', ['10,60', '24,4', '22,6'], '0,1 mol Na₂CO₃ ve 0,2 mol SiO₂ vardır; Na₂CO₃ sınırlayıcıdır. 0,1 mol Na₂SiO₃ = 0,1 × 122 = 12,2 g oluşur.'),
  ('Çamaşır suyu üretiminde Cl₂ + 2NaOH → NaCl + NaClO + H₂O tepkimesi kullanılır. 7,1 g Cl₂ fazla NaOH ile tepkimeye girerse kaç gram NaClO oluşur? (Na = 23, O = 16, Cl = 35,5)', '7,45', ['3,730', '14,9', '5,85'], '7,1 / 71 = 0,1 mol Cl₂ 0,1 mol NaClO verir. Mol kütlesi 74,5 g/mol; kütle 7,45 g\'dır.'),
  ('Alüminyum ile sodyum hidroksit arasındaki 2Al + 2NaOH + 6H₂O → 2NaAl(OH)₄ + 3H₂ tepkimesinde 2,7 g Al tamamen harcanırsa normal koşullarda kaç litre H₂ oluşur? (Al = 27)', '3,36', ['2,240', '1,12', '6,72'], '2,7 / 27 = 0,1 mol Al ve H₂ : Al oranı 3 : 2\'dir; 0,15 mol H₂ oluşur. Hacim 0,15 × 22,4 = 3,36 L\'dir.'),
  ('Silisyum üretiminde SiO₂ + 2C → Si + 2CO tepkimesi kullanılıyor. 120 g SiO₂\'den %80 verimle kaç gram silisyum elde edilir? (Si = 28, O = 16)', '44,8', ['56', '28', '35,00'], '120 / 60 = 2 mol SiO₂ kuramsal olarak 2 mol Si (56 g) verir. %80 verimle 56 × 0,80 = 44,8 g elde edilir.'),
  ('Nitrik asit üretiminde amonyak NO\'ya, NO NO₂\'ye, NO₂ da su ile HNO₃\'e dönüştürülür ve oluşan NO geri döndürülerek yeniden kullanılır. 34 g NH₃\'ten en çok kaç gram HNO₃ elde edilebilir? (N = 14, H = 1, O = 16)', '126', ['63', '252,0', '34'], '34 / 17 = 2 mol NH₃ ve her azot atomu HNO₃\'e geçer; 2 mol HNO₃ oluşur. Kütle 2 × 63 = 126 g\'dır.'),
  ('İtfaiyecilerin ve madencilerin solunum cihazlarında 4KO₂ + 2CO₂ → 2K₂CO₃ + 3O₂ tepkimesinden yararlanılır. 7,1 g KO₂ (71 g/mol) tamamen tepkimeye girerse kaç gram O₂ açığa çıkar?', '2,4', ['1,60', '3,2', '4,8'], '7,1 / 71 = 0,1 mol KO₂; O₂ : KO₂ oranı 3 : 4 olduğundan 0,075 mol O₂ oluşur. Kütle 0,075 × 32 = 2,4 g\'dır.'),
  ('Uzay aracı kabininde CO₂ tutmak için 2LiOH + CO₂ → Li₂CO₃ + H₂O tepkimesi kullanılıyor. 4,8 g LiOH (24 g/mol) en çok kaç gram CO₂ tutabilir? (C = 12, O = 16)', '4,4', ['2,20', '8,8', '9,6'], '4,8 / 24 = 0,2 mol LiOH; CO₂ : LiOH oranı 1 : 2 olduğundan 0,1 mol CO₂ tutulur. Kütle 0,1 × 44 = 4,4 g\'dır.'),
  ('Sahada hidrojen üretiminde CaH₂ + 2H₂O → Ca(OH)₂ + 2H₂ tepkimesi kullanılır. 4,2 g CaH₂ (42 g/mol) tamamen tepkimeye girerse normal koşullarda kaç litre H₂ açığa çıkar?', '4,48', ['2,240', '8,96', '1,12'], '4,2 / 42 = 0,1 mol CaH₂ 0,2 mol H₂ verir. Hacim 0,2 × 22,4 = 4,48 L\'dir.'),
  ('Sönmüş kireçli harcın sertleşmesinde Ca(OH)₂ + CO₂ → CaCO₃ + H₂O tepkimesi gerçekleşir. 7,4 kg Ca(OH)₂ havadan tamamen CO₂ bağlarsa kaç kilogram CO₂ harcanır? (Ca = 40, O = 16, C = 12, H = 1)', '4,4', ['7,4', '2,2', '10,0'], '7400 g / 74 = 100 mol Ca(OH)₂ ve 100 mol CO₂ bağlanır. Kütle 100 × 44 = 4400 g = 4,4 kg\'dır.'),
  ('Kurşun-asit akünün boşalmasında Pb + PbO₂ + 2H₂SO₄ → 2PbSO₄ + 2H₂O tepkimesi gerçekleşir. 0,1 mol Pb harcandığında kaç gram H₂SO₄ tüketilir? (H = 1, S = 32, O = 16)', '19,6', ['9,8', '39,20', '98'], 'Pb : H₂SO₄ katsayı oranı 1 : 2 olduğundan 0,2 mol H₂SO₄ harcanır. Kütle 0,2 × 98 = 19,6 g\'dır.'),
  ('Oksijen mumlarında 2NaClO₃ → 2NaCl + 3O₂ tepkimesi kullanılır. 21,3 g NaClO₃ (106,5 g/mol) tamamen ayrışırsa kaç gram O₂ elde edilir?', '9,6', ['6,4', '14,4', '3,2'], '21,3 / 106,5 = 0,2 mol NaClO₃; O₂ : NaClO₃ oranı 3 : 2 olduğundan 0,3 mol O₂ oluşur. Kütle 0,3 × 32 = 9,6 g\'dır.'),
  ('63,2 g KMnO₄ (158 g/mol) ısıtılarak 2KMnO₄ → K₂MnO₄ + MnO₂ + O₂ tepkimesiyle tamamen ayrıştırılıyor. Açığa çıkan O₂ kaç gramdır?', '6,4', ['3,2', '12,8', '63,2'], '63,2 / 158 = 0,4 mol KMnO₄; O₂ : KMnO₄ oranı 1 : 2 olduğundan 0,2 mol O₂ oluşur. Kütle 0,2 × 32 = 6,4 g\'dır.'),
];
